#include <iostream>
#include <memory>

class Query {
public:
    virtual bool evaluate() = 0;
    virtual ~Query() = default;
};

class LiteralQuery : public Query {
public:
    bool evaluate() override { return true; }
};

class AndQuery {
    std::unique_ptr<Query> left, right;
public:
    AndQuery(std::unique_ptr<Query> l, std::unique_ptr<Query> r)
        : left(std::move(l)), right(std::move(r)) {}
    bool evaluate() { return left->evaluate() && right->evaluate(); }
};

int main() {
    auto lit1 = std::make_unique<LiteralQuery>();
    auto lit2 = std::make_unique<LiteralQuery>();
    AndQuery andQ(std::move(lit1), std::move(lit2));
    std::cout << andQ.evaluate() << std::endl; // Outputs 1
    return 0;
}

