int main() {
    std::map<std::string, int> m;

    // Access/insert existing or new key
    m["hello"] = 5;
    std::cout << "m['hello']: " << m["hello"] << std::endl;  // Outputs 5

    std::cout << "m['world'] (new): " << m["world"] << std::endl;  // Outputs 0, inserts key

    // Common pitfall: [] inserts if key missing
    std::cout << "Size before bad check: " << m.size() << std::endl;  // 2
    if (m["foo"]) {  // Inserts 'foo' with 0!
        std::cout << "Key exists" << std::endl;
    }
    std::cout << "Size after bad check: " << m.size() << std::endl;  // 3

    // Safe alternative: use find()
    if (m.find("bar") == m.end()) {
        std::cout << "'bar' does not exist (no insertion)" << std::endl;
    }

    return 0;
}

