public:
    MyClass(const char* s) {
        data = new char[strlen(s) + 1];
        strcpy(data, s);
    }
    ~MyClass() {
        delete[] data;
    }
    MyClass& operator=(const MyClass& other) {
        if (this != &other) {
            delete[] data;
            data = new char[strlen(other.data) + 1];
            strcpy(data, other.data);
        }
        return *this;
    }
    const char* getData() const { return data; }
};

