    MyClass b("world");
    b = a;
    std::cout << b.getData() << std::endl;
    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    char str[] = "Hello, World!";
    char* p = str;
    p += 7;  // Pointer arithmetic for substring slicing
    std::cout << p << std::endl;  // Outputs: World!

    // In-place reverse using pointers
    char* start = str;
    char* end = str + std::strlen(str) - 1;
    while (start < end) {
        char temp = *start;
        *start++ = *end;
        *end-- = temp;
    }
    std::cout << str << std::endl;  // Outputs: !dlroW ,olleH
    return 0;
}

