#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* name;
} Person;

Person* copy_person(const Person* p) {
    Person* newp = malloc(sizeof(Person));
    newp->name = strdup(p->name);
    return newp;
}

typedef Person* (*CopyFunc)(const Person*);

struct Container {
    Person* person;
    CopyFunc copy;
};

int main() {
    Person* p = malloc(sizeof(Person));
    p->name = strdup("Alice");
    struct Container c = {p, copy_person};
    struct Container c2 = {c.copy(c.person), c.copy};
    printf("%s\n", c2.person->name);
    free(p->name); free(p);
    free(c2.person->name); free(c2.person);
    return 0;
}

#include <iostream>

int main() {
    // Signed loop: terminates correctly
    std::cout << "Signed loop:\n";
    for (int i = 5; i >= 0; --i) {
        std::cout << i << ' ';
    }
    std::cout << "\nDone signed.\n";

    // Unsigned loop: infinite due to underflow (i becomes UINT_MAX after 0)
    std::cout << "Unsigned loop (will not terminate):\n";
    for (unsigned int j = 5; j >= 0; --j) {
        std::cout << j << ' ';
        if (j == 1) { // Break early to avoid actual infinite loop in demo
            std::cout << "\n(Stopped early; in reality, it would loop forever after 0)\n";
            break;
        }
    }
    return 0;
}

