#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int ref_count;
    char* data;
} SharedString;

SharedString* create_shared(const char* str) {
    SharedString* s = malloc(sizeof(SharedString));
    s->ref_count = 1;
    s->data = strdup(str);
    return s;
}

void retain(SharedString* s) {
    if (s) s->ref_count++;
}

void release(SharedString* s) {
    if (s && --s->ref_count == 0) {
        free(s->data);
        free(s);
    }
}

int main() {
    SharedString* s1 = create_shared("Hello");
    SharedString* s2 = s1;
    retain(s2);
    printf("%s\n", s1->data);
    release(s1);
    release(s2);
    return 0;
}

