int main() {
    // Safe decrement loop with unsigned: use != 0 instead of >= 0
    std::cout << "Safe unsigned decrement loop:\n";
    unsigned int i = 5;
    while (i != 0) {
        std::cout << i << " ";
        --i;
    }
    std::cout << "\n(Outputs: 5 4 3 2 1)\n\n";

    // Risky signed/unsigned mismatch in loop condition
    std::cout << "Signed/unsigned mismatch risk:\n";
    int signed_len = 3;  // If this were -1, loop would run ~4B times due to implicit conversion
    for (unsigned int j = 0; j < static_cast<unsigned int>(signed_len); ++j) {
        std::cout << j << " ";
    }
    std::cout << "\n(Outputs: 0 1 2; cast avoids mismatch)\n";

    // Without cast, if signed_len = -1: for(unsigned j=0; j < -1; ++j) becomes j < UINT_MAX, infinite-like loop
    return 0;
}

