int main() {
    // Signed loop: terminates correctly
    std::cout << "Signed loop:\n";
    for (int i = 2; i >= 0; --i) {
        std::cout << i << std::endl;
    }
    std::cout << "Signed loop ended.\n\n";

    // Unsigned loop: infinite in practice due to underflow to UINT_MAX
    std::cout << "Unsigned loop (conceptual; runs infinitely):\n";
    for (unsigned int u = 2; u >= 0; --u) {
        std::cout << u << std::endl;
        // After u=0, --u sets u=UINT_MAX, and UINT_MAX >= 0 is true
    }
    // This line is never reached
