#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int* data;
    int ref_count;
} SharedInt;

SharedInt* create_shared(int val) {
    SharedInt* s = malloc(sizeof(SharedInt));
    s->data = malloc(sizeof(int));
    *s->data = val;
    s->ref_count = 1;
    return s;
}

void retain(SharedInt* s) {
    if (s) s->ref_count++;
}

void release(SharedInt* s) {
    if (s && --s->ref_count == 0) {
        free(s->data);
        free(s);
    }
}

int main() {
    SharedInt* a = create_shared(42);
    SharedInt* b = a;
    retain(b);
    printf("%d\n", *a->data);
    release(a);
    release(b);
    return 0;
}

