    int y;
};

int main() {
    // Positional initializer: must follow declaration order
    struct Point p1 = {1, 2};  // x=1, y=2 (correct)
    struct Point p2 = {3, 4};  // If order swapped in intent, gets x=3, y=4 (but shows order matters)

    // Misordered positional (intent: x=5, y=6, but writes y=5, x=6 due to order)
    struct Point p3 = {6, 5};

    // Designated initializers: order in list doesn't matter, maps by name to declaration order
    struct Point p4 = {.y = 7, .x = 8};  // Still x=8, y=7

    printf("p1: x=%d, y=%d\n", p1.x, p1.y);
    printf("p2: x=%d, y=%d\n", p2.x, p2.y);
    printf("p3 (misordered): x=%d, y=%d\n", p3.x, p3.y);
    printf("p4 (designated): x=%d, y=%d\n", p4.x, p4.y);

    return 0;
}

