typedef void* (*CopyCallback)(const void*);

void* int_copy(const void* src) {
    int* dest = malloc(sizeof(int));
    *dest = *(int*)src;
    return dest;
}

void* custom_copy(const void* src) {
    char* dest = malloc(10);
    snprintf(dest, 10, "custom:%d", *(int*)src);
    return dest;
}

void* perform_copy(const void* data, CopyCallback cb) {
    return cb(data);
}

int main() {
    int val = 42;
    void* copy1 = perform_copy(&val, int_copy);
    printf("Standard copy: %d\n", *(int*)copy1);
    free(copy1);

    void* copy2 = perform_copy(&val, custom_copy);
    printf("Custom copy: %s\n", (char*)copy2);
    free(copy2);
    return 0;
}

