#include <iostream>
#include <limits>

int main() {
    // Demonstrating unsigned underflow leading to infinite loops
    unsigned int counter = 1;
    std::cout << "Unsigned underflow simulation:\n";
    std::cout << "counter = " << counter << ", >=0? Yes\n";
    --counter;  // now 0
    std::cout << "After --, counter = " << counter << ", >=0? Yes\n";
    --counter;  // now UINT_MAX
    std::cout << "After another --, counter = " << counter << ", >=0? Yes (wrap around)\n";
    std::cout << "This causes infinite loops like for(unsigned i=10; i>=0; --i) {}\n\n";

    // Safe signed loop
    std::cout << "Safe signed loop:\n";
    for(int i = 5; i >= 0; --i) {
        std::cout << i << " ";
    }
    std::cout << std::endl;

    return 0;
}

