int main() {
    int max_int = std::numeric_limits<int>::max();
    int a = max_int;
    int b = 1;

    // Overflow example: wraps around to negative
    std::cout << "Overflow: " << a + b << std::endl;

    // Prevention: check before addition
    if (a > max_int - b) {
        std::cout << "Would overflow, skipping addition." << std::endl;
    } else {
        std::cout << "Safe addition: " << a + b << std::endl;
    }

    // Alternative: use larger type
    long long safe_a = a;
    long long safe_b = b;
    std::cout << "Safe with long long: " << safe_a + safe_b << std::endl;

    return 0;
}

