#include <iostream>
#include <vector>

int main() {
    std::vector<int> vec{1, 2, 3};

    // Bad: Off-by-one error - loop runs one extra iteration
    std::cout << "Off-by-one error (prints extra index):\n";
    for(size_t i = 0; i < vec.size() + 1; ++i) {
        std::cout << i << " ";
    }
    std::cout << "\nExpected: 0 1 2, but got extra 3\n\n";

    // Good: Correct boundary (exclusive upper bound)
    std::cout << "Correct off-by-one handling:\n";
    for(size_t i = 0; i < vec.size(); ++i) {
        std::cout << i << " ";
    }
    std::cout << "\n\n";

    // Bad: Unsigned integer underflow
    std::cout << "Unsigned underflow:\n";
    unsigned int u = 0;
    std::cout << "Before --u: " << u << std::endl;
    --u;
    std::cout << "After --u: " << u << std::endl;  // Wraps to UINT_MAX
    std::cout << "This can cause infinite loops if used in conditions.\n";

    // Good: Use signed int to avoid underflow
    std::cout << "\nCorrect: Using signed int:\n";
    int s = 0;
    std::cout << "Before --s: " << s << std::endl;
    --s;
    std::cout << "After --s: " << s << std::endl;  // -1, as expected

    return 0;
}

