class Base1 {
public:
    std::unique_ptr<int> ptr{std::make_unique<int>(10)};
    Base1(const Base1& other) : ptr(std::make_unique<int>(*other.ptr)) {}
    Base1(Base1&& other) noexcept : ptr(std::move(other.ptr)) {}
};

class Base2 {
public:
    std::unique_ptr<int> ptr{std::make_unique<int>(20)};
    Base2(const Base2& other) : ptr(std::make_unique<int>(*other.ptr)) {}
    Base2(Base2&& other) noexcept : ptr(std::move(other.ptr)) {}
};

class Derived : public Base1, public Base2 {
public:
    int value = 30;
    // Explicitly call base copy/move to handle resources
    Derived(const Derived& other) : Base1(other), Base2(other), value(other.value) {
        std::cout << "Derived copy ctor\n";
    }
    Derived(Derived&& other) noexcept : Base1(std::move(other)), Base2(std::move(other)), value(other.value) {
        std::cout << "Derived move ctor\n";
    }
};

int main() {
    Derived d1;
    Derived d2 = d1;  // copy
    Derived d3 = std::move(d1);  // move
    std::cout << *d2.ptr << " " << *d2.Base2::ptr << " " << d2.value << std::endl;
    return 0;
}

