#include <iostream>

class ResourceClass {  // Rule of Five: manages raw pointer
private:
    int* ptr;
public:
    ResourceClass() : ptr(new int(42)) {}
    ~ResourceClass() { delete ptr; }
    ResourceClass(const ResourceClass& other) : ptr(new int(*other.ptr)) {}
    ResourceClass& operator=(const ResourceClass& other) {
        if (this != &other) {
            delete ptr;
            ptr = new int(*other.ptr);
        }
        return *this;
    }
    // Move ctor/assign omitted for brevity
    int get() const { return *ptr; }
};

class SimpleClass {  // Rule of Zero: no external resources
public:
    int value;
    SimpleClass(int v) : value(v) {}
    // Compiler generates all special members correctly
};

int main() {
    ResourceClass res;
    ResourceClass copy = res;  // Uses custom copy ctor
    SimpleClass simple(10);
    SimpleClass simpleCopy = simple;  // Uses compiler-generated
    std::cout << res.get() << ' ' << simple.value << std::endl;
    return 0;
}

