#include <string>

int main() {
    std::map<std::string, int> m;

    // Unsafe: operator[] inserts default value for non-existent key
    std::cout << "Unsafe access (inserts default 0): " << m["key"] << std::endl;

    // Safe: check existence before access
    auto it = m.find("key");
    if (it != m.end()) {
        std::cout << "Value: " << it->second << std::endl;
    } else {
        std::cout << "Key not found, no insertion" << std::endl;
        // Safe insertion
        m.try_emplace("newkey", 42);
        std::cout << "Safe insert: " << m["newkey"] << std::endl;
    }

    return 0;
}

