#include <iostream>

class Resource {
private:
    int* data;
public:
    Resource() : data(new int[5]) {
        std::cout << "Resource acquired\n";
    }
    ~Resource() {
        delete[] data;
        std::cout << "Resource released\n";
    }
    Resource(const Resource& other) : data(new int[5]) {
        std::cout << "Copy constructed\n";
    }
    Resource& operator=(const Resource& other) {
        if (this != &other) {
            delete[] data;
            data = new int[5];
        }
        std::cout << "Copy assigned\n";
        return *this;
    }
    Resource(Resource&& other) noexcept : data(other.data) {
        other.data = nullptr;
        std::cout << "Move constructed\n";
    }
    Resource& operator=(Resource&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            other.data = nullptr;
        }
        std::cout << "Move assigned\n";
        return *this;
    }
};

int main() {
    Resource r1;
    Resource r2 = r1;  // Copy
    Resource r3 = std::move(r1);  // Move
    return 0;
}

