int main() {
    // Bad: Unsigned underflow in decrementing loop leads to infinite loop
    // unsigned int i = 0;
    // do {
    //     std::cout << "Processing " << i << std::endl;
    //     --i;
    // } while (i != 0);  // i wraps to UINT_MAX, never 0

    // Good: Initialize properly and check > 0 to avoid underflow
    std::cout << "Good loop:\n";
    unsigned int i = 5;
    while (i > 0) {
        std::cout << "Processing " << i << std::endl;
        --i;
    }

    // Bad: Signed/unsigned mismatch in comparison
    // unsigned int a = 1;
    // int b = -1;
    // if (a > b) { ... }  // b promotes to UINT_MAX, so false unexpectedly

    // Good: Avoid mixing; cast or use same type
    unsigned int a = 1;
    unsigned int b = 0;  // Treat as unsigned
    if (a > b) {
        std::cout << "a > b is true (no mismatch)" << std::endl;
    }

    return 0;
}

