#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
    struct Node* (*copy)(struct Node*);
} Node;

Node* copy_node(Node* src) {
    if (!src) return NULL;
    Node* dest = malloc(sizeof(Node));
    dest->data = src->data;
    dest->next = src->copy(src->next);
    dest->copy = copy_node;
    return dest;
}

int main() {
    Node* n1 = malloc(sizeof(Node));
    n1->data = 42;
    n1->next = NULL;
    n1->copy = copy_node;
    Node* n2 = n1->copy(n1);
    printf("%d\n", n2->data);
    free(n1);
    free(n2);
    return 0;
}

