#include <iostream>

struct Node {
    int key;
    int value;
    Node* next;
    Node(int k, int v, Node* n) : key(k), value(v), next(n) {}
};

class HashTable {
private:
    static const int SIZE = 10;
    Node* table[SIZE];
public:
    HashTable() {
        for (int i = 0; i < SIZE; ++i) table[i] = nullptr;
    }
    ~HashTable() {
        for (int i = 0; i < SIZE; ++i) {
            Node* curr = table[i];
            while (curr) {
                Node* temp = curr;
                curr = curr->next;
                delete temp;
            }
        }
    }
    void insert(int key, int value) {
        int index = key % SIZE;
        table[index] = new Node(key, value, table[index]);
    }
    void print() {
        for (int i = 0; i < SIZE; ++i) {
            Node* curr = table[i];
            while (curr) {
                std::cout << "Bucket " << i << ": Key=" << curr->key << ", Value=" << curr->value << std::endl;
                curr = curr->next;
            }
        }
    }
};

int main() {
    HashTable ht;
    ht.insert(1, 10);
    ht.insert(11, 20);  // same bucket
    ht.print();
    return 0;
}

