#include <iostream>

int main() {
    unsigned int flags = 0b00001101; // Bits 0, 2, 3 set (1+4+8=13)

    // Complex expression: Check if (bit 0 set) && (bits 2|3 set), using precedence
    // flags & 1 && (flags & 0b110) : & higher than &&, so groups correctly without extra parens
    bool condition = (flags & 1) && (flags & 0b110);

    // Bitwise manipulation: Clear bit 2 if condition, else set bit 4
    // Relies on ? : precedence over | and & (ternary lowest among these)
    unsigned int result = condition ? (flags & ~0b100) : (flags | 0b10000);

    std::cout << "Flags: " << std::bitset<8>(flags) << std::endl;
    std::cout << "Condition: " << condition << std::endl;
    std::cout << "Result: " << std::bitset<8>(result) << std::endl;

    return 0;
}

