#include <regex.h>

int main() {
    regex_t regex;
    int ret = regcomp(&regex, "(\\d{3})-(\\d{3})-(\\d{4})", REG_EXTENDED);
    if (ret != 0) {
        printf("Regex compilation failed\n");
        return 1;
    }

    const char *str = "123-456-7890";
    regmatch_t matches[4];
    if (regexec(&regex, str, 4, matches, 0) == 0) {
        for (int i = 1; i < 4; i++) {
            int start = matches[i].rm_so;
            int end = matches[i].rm_eo;
            if (start != -1) {
