#include <iostream>
#include <vector>

int main() {
    std::vector<int> v = {10, 20, 30};

    // Off-by-one error with indices
    std::cout << "Off-by-one example (bad loop accesses one extra):\n";
    for (size_t i = 0; i <= v.size(); ++i) {
        if (i < v.size()) {
            std::cout << v[i] << " ";
        } else {
            std::cout << "[Out of bounds!] ";
        }
    }
    std::cout << "\n";

    // Integer underflow with unsigned (infinite loop risk)
    std::cout << "Underflow example (unsigned loop doesn't stop):\n";
    size_t count = 0;
    for (size_t i = 0; i > 0; --i) {
        ++count;
        if (count > 5) break;  // Demo limit to avoid infinite
        std::cout << "Unexpected iteration " << count << "\n";
    }
    std::cout << "Ran " << count << " times instead of 0.\n";

    // Good: Use signed int to avoid underflow
    int j = 0;
    while (j > 0) --j;
    std::cout << "Signed loop: 0 iterations (correct).\n";

    // Correct iterator loop (avoids off-by-one)
    std::cout << "Correct iterator loop:\n";
    for (auto it = v.begin(); it != v.end(); ++it) {
        std::cout << *it << " ";
    }
    std::cout << "\n";

    return 0;
}

