#include <iostream>

struct Node {
    int key;
    int value;
    Node* next;
    Node(int k, int v, Node* n) : key(k), value(v), next(n) {}
};

class HashTable {
    Node** table;
    int size;
public:
    HashTable(int s) : size(s) {
        table = new Node*[size]();
    }
    ~HashTable() {
        for(int i = 0; i < size; ++i) {
            Node* n = table[i];
            while(n) {
                Node* temp = n;
                n = n->next;
                delete temp;
            }
        }
        delete[] table;
    }
    void insert(int k, int v) {
        int h = k % size;
        table[h] = new Node(k, v, table[h]);
    }
    int get(int k) {
        int h = k % size;
        for(Node* n = table[h]; n; n = n->next) {
            if(n->key == k) return n->value;
        }
        return -1;
    }
};

int main() {
    HashTable ht(10);
    ht.insert(1, 100);
    ht.insert(11, 200);
    std::cout << ht.get(1) << std::endl;
    return 0;
}

