#include <iostream>

struct Node {
    int data;
    Node* next;
    Node* prev;
};

int main() {
    Node n1{1, nullptr, nullptr};
    Node n2{2, nullptr, nullptr};
    Node n3{3, nullptr, nullptr};

    // Build doubly linked list: n1 <-> n2 <-> n3
    n1.next = &n2; n2.prev = &n1;
    n2.next = &n3; n3.prev = &n2;

    // Demonstrate aliasing: n1.next and n2.prev both point to n2
    std::cout << "n1.next->data: " << n1.next->data << std::endl;
    std::cout << "n2.prev->data: " << n2.prev->data << std::endl;

    // Manipulation: Remove n2 by updating pointers
    n1.next = n2.next;
    n3.prev = n2.prev;

    // Now n1.next and n3.prev alias to n3? No, to n1? Wait, after removal: n1.next = &n3, n3.prev = &n1
    std::cout << "After removal, list: ";
    for (Node* cur = &n1; cur; cur = cur->next) {
        std::cout << cur->data << " ";
    }
    std::cout << std::endl;

    return 0;
}

