#include <deque>
#include <iostream>

template<typename T>
class DequeStackAdapter {
private:
    std::deque<T> deque_;
public:
    void push(const T& item) { deque_.push_back(item); }
    T pop() {
        T item = deque_.back();
        deque_.pop_back();
        return item;
    }
    T top() const { return deque_.back(); }
    bool empty() const { return deque_.empty(); }
};

int main() {
    DequeStackAdapter<int> stack;
    stack.push(1);
    stack.push(2);
    std::cout << stack.top() << std::endl; // Outputs: 2
    std::cout << stack.pop() << std::endl; // Outputs: 2
    return 0;
}

