#include <errno.h>

int main(void) {
    int dir_fd = open(".", O_PATH | O_CLOEXEC);
    if (dir_fd < 0) {
        perror("open");
        return 1;
    }

    int ruleset_fd = syscall(SYS_landlock_create_ruleset, LANDLOCK_RULESET_VERSION, 0);
    if (ruleset_fd < 0) {
        perror("landlock_create_ruleset");
        close(dir_fd);
        return 1;
    }

    struct landlock_rule_attr rule = {
        .allowed_access = LANDLOCK_ACCESS_O_PATH | LANDLOCK_ACCESS_O_RDONLY,
        .path_beneath = dir_fd,
    };

    if (syscall(SYS_landlock_add_rule, ruleset_fd, LANDLOCK_RULE_PATH_BENEATH, &rule, 0) < 0) {
        perror("landlock_add_rule");
        close(ruleset_fd);
        close(dir_fd);
        return 1;
    }

    close(dir_fd);

    if (syscall(SYS_landlock_restrict_self, ruleset_fd, 0) < 0) {
        perror("landlock_restrict_self");
        close(ruleset_fd);
        return 1;
    }

    close(ruleset_fd);
    printf("Landlock restrictions applied successfully.\n");
