        std::cerr << "semop wait failed" << std::endl;
        return 1;
    }
    std::cout << "In critical section" << std::endl;
    sop.sem_op = 1; // signal
    if (semop(semid, &sop, 1) == -1) {
        std::cerr << "semop signal failed" << std::endl;
        return 1;
    }
    return 0;
}

