#define SYS_pidfd_open 263
#define SYS_pidfd_getfd 432

int main() {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }
    if (pid == 0) { // child
        close(pipefd[0]);
        int fd = open("/dev/null", O_RDONLY);
        if (fd == -1) {
            perror("open");
            exit(1);
        }
        write(pipefd[1], &fd, sizeof(int));
        close(pipefd[1]);
        pause();
        close(fd);
        return 0;
    } // parent
    close(pipefd[1]);
    int targetfd;
    read(pipefd[0], &targetfd, sizeof(int));
    close(pipefd[0]);
    long pidfd_long = syscall(SYS_pidfd_open, pid, 0);
    if (pidfd_long == -1) {
        perror("pidfd_open");
        return 1;
    }
    int pidfd = (int)pidfd_long;
    long newfd_long = syscall(SYS_pidfd_getfd, pidfd, targetfd, 0);
    if (newfd_long == -1) {
        perror("pidfd_getfd");
        close(pidfd);
        return 1;
    }
    int newfd = (int)newfd_long;
    printf("Duplicated fd: %d\n", newfd);
    close(newfd);
    close(pidfd);
    kill(pid, SIGTERM);
    wait(NULL);
    return 0;
}

