        perror("landlock_add_rule");
        close(dir_fd);
        close(ruleset_fd);
        return 1;
    }

    if (syscall(__NR_landlock_restrict_self, ruleset_fd, 0) == -1) {
        perror("landlock_restrict_self");
    }

