        sleep(5); // wait for parent to join
        return 0;
    } else { // parent
        sleep(1);
        char path[64];
        snprintf(path, sizeof(path), "/proc/%d/ns/uts", pid);
        int fd = open(path, O_RDONLY | O_CLOEXEC);
        if (fd == -1) {
            perror("open");
            waitpid(pid, NULL, 0);
