        }
        if (setns(fd, CLONE_NEWUTS) == -1) {
            perror("setns");
            close(fd);
            waitpid(pid, NULL, 0);
            return 1;
        }
        close(fd);
        char hostname[256];
        gethostname(hostname, sizeof(hostname));
        printf("Parent after setns: %s\n", hostname);
        waitpid(pid, NULL, 0);
    }
