#include <sys/mman.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

int pkey_mprotect(void *addr, size_t len, int prot, int pkey) {
    return syscall(__NR_pkey_mprotect, addr, len, prot, pkey);
}

int main() {
    int pkey = syscall(__NR_pkey_alloc, 0, 0);
    if (pkey < 0) {
        perror("pkey_alloc");
        return 1;
    }
    void *mem = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        syscall(__NR_pkey_free, pkey);
        return 1;
    }
    if (pkey_mprotect(mem, 4096, PROT_READ, pkey) == -1) {
        perror("pkey_mprotect");
        munmap(mem, 4096);
        syscall(__NR_pkey_free, pkey);
        return 1;
    }
    // Memory now protected with read-only and key pkey
    munmap(mem, 4096);
    syscall(__NR_pkey_free, pkey);
    return 0;
}

