#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int fd[2];
    pipe(fd);
    pid_t pid = fork();
    if (pid == 0) { // child
        close(fd[0]);
        char buf[10] = {0};
        write(fd[1], &buf, sizeof(buf));
        close(fd[1]);
        sleep(2);
        printf("Child buffer: %s\n", buf);
        return 0;
    }
    // parent
    close(fd[1]);
    char remote_buf[10];
    read(fd[0], remote_buf, sizeof(remote_buf));
    close(fd[0]);
    char data[] = "Hello";
    struct iovec liov = {data, strlen(data)};
    struct iovec riov = {remote_buf, strlen(data)};
    ssize_t res = syscall(SYS_process_vm_writev, pid, &liov, 1, &riov, 1, 0);
    if (res > 0) printf("Wrote %zd bytes to child\n", res);
    wait(NULL);
    return 0;
}

