#include <sys/mman.h>
#include <sys/types.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

int main() {
    size_t page_size = getpagesize();
    void* addr = mmap(NULL, page_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        return 1;
    }
    unsigned char vec[1];
    // Query before touching (likely not resident)
    if (mincore(addr, page_size, vec) == -1) {
        perror("mincore before");
    } else {
        printf("Before touch: resident = %d\n", vec[0] & 1);
    }
    // Touch to cause page fault and residency
    *(char*)addr = 1;
    if (mincore(addr, page_size, vec) == -1) {
        perror("mincore after");
    } else {
        printf("After touch: resident = %d\n", vec[0] & 1);
    }
    munmap(addr, page_size);
    return 0;
}

