int main() {
    int epfd = epoll_create1(0);
    if (epfd < 0) return 1;

    int pipefd[2];
    if (pipe(pipefd) < 0) return 1;

    struct epoll_event ev = {};
    ev.events = EPOLLIN;
    ev.data.fd = pipefd[0];
    if (epoll_ctl(epfd, EPOLL_CTL_ADD, pipefd[0], &ev) < 0) return 1;

    char buf[] = "a";
    write(pipefd[1], buf, 1);

    struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
    sigset_t mask;
    sigemptyset(&mask);
    sigaddset(&mask, SIGINT);

    struct epoll_event events[1];
    int nfds = epoll_pwait2(epfd, events, 1, &ts, &mask, sizeof(sigset_t));

    std::cout << "Number of events: " << nfds << std::endl;

    close(pipefd[0]);
    close(pipefd[1]);
    close(epfd);
    return 0;
}

