int main() {
    int prio = IOPRIO_PRIO_VALUE(IOPRIO_CLASS_BE, 7); // Best-effort class, priority 7
    int ret = ioprio_set(IOPRIO_WHO_PROCESS, getpid(), prio);
    if (ret == -1) {
        if (errno == EPERM) {
