#include <signal.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    sigset_t block, old;
    sigemptyset(&block);
    sigaddset(&block, SIGUSR1);
    sigprocmask(SIG_BLOCK, &block, &old);
    kill(getpid(), SIGUSR1);
    sigset_t pending;
    if (syscall(SYS_rt_sigpending, &pending, sizeof(sigset_t)) == -1) {
        perror("rt_sigpending");
        return 1;
    }
    if (sigismember(&pending, SIGUSR1)) {
        printf("SIGUSR1 is pending.\n");
    }
    sigprocmask(SIG_SETMASK, &old, NULL);
    return 0;
}

