        return 1;
    }
    struct io_event events[1];
    int r = io_getevents(ctx, 1, 1, events, NULL);
    if (r < 0) perror("io_getevents");
    close(fd);
    io_destroy(ctx);
    printf("AIO context destroyed.\n");
    return 0;
}

