std::uint32_t futex_var = 0;

void* waiter(void*) {
    syscall(SYS_futex, &futex_var, FUTEX_WAIT, 0, nullptr, nullptr, 0);
    std::cout << "Waiter woke up!" << std::endl;
    return nullptr;
}

void* waker(void*) {
    sleep(1);
    futex_var = 1;
    syscall(SYS_futex, &futex_var, FUTEX_WAKE, 1, nullptr, nullptr, 0);
    return nullptr;
}

int main() {
    pthread_t t1, t2;
