#include <sys/eventfd.h>
#include <unistd.h>
#include <iostream>
#include <cstdint>

int main() {
    int efd = eventfd(0, 0);
    if (efd == -1) {
        std::cerr << "eventfd failed" << std::endl;
        return 1;
    }

    uint64_t val = 1;
    if (write(efd, &val, sizeof(val)) != sizeof(val)) {
        std::cerr << "write failed" << std::endl;
        close(efd);
        return 1;
    }

    uint64_t u;
    if (read(efd, &u, sizeof(u)) != sizeof(u)) {
        std::cerr << "read failed" << std::endl;
        close(efd);
        return 1;
    }

    std::cout << "Read value: " << u << std::endl;
    close(efd);
    return 0;
}

#include <sys/syscall.h>
#include <linux/seccomp.h>
#include <unistd.h>
#include <stdio.h>
#include <errno.h>

int main() {
    long ret = syscall(SYS_seccomp, SECCOMP_SET_MODE_STRICT, 0, NULL);
    if (ret == -1) {
        perror("seccomp");
        return 1;
    }
    printf("Seccomp strict mode set successfully.\n");

    // Attempt an invalid syscall (open) in strict mode
    FILE *f = fopen("/etc/passwd", "r");
    if (f) {
        fclose(f);
        printf("Unexpected: fopen succeeded.\n");
    } else {
        perror("fopen (expected failure)");
    }
    return 0;
}

#include <unistd.h>
#include <fcntl.h>
#include <iostream>
#include <sys/stat.h>

int main() {
    // Create original file
    int fd = open("original.txt", O_CREAT | O_WRONLY, 0644);
    if (fd == -1) {
        std::cerr << "open failed\n";
        return 1;
    }
    close(fd);

    // Create hard link using linkat
    int ret = linkat(AT_FDCWD, "original.txt", AT_FDCWD, "link.txt", 0);
    if (ret == -1) {
        std::cerr << "linkat failed\n";
        unlink("original.txt");
        return 1;
    }

    std::cout << "Hard link created successfully\n";

    // Cleanup
    unlink("link.txt");
    unlink("original.txt");

    return 0;
}

