#include <iostream>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <arpa/inet.h>

int main() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        std::cerr << "Socket creation failed" << std::endl;
        return 1;
    }

    sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sock, (sockaddr*)&addr, sizeof(addr)) < 0) {
        std::cerr << "Bind failed" << std::endl;
        close(sock);
        return 1;
    }

    listen(sock, 1);
    std::cout << "Server listening on port 8080" << std::endl;

    sockaddr_in client_addr;
    socklen_t len = sizeof(client_addr);
    int client = accept(sock, (sockaddr*)&client_addr, &len);
    if (client >= 0) {
        std::cout << "Client connected" << std::endl;
        close(client);
    }

    close(sock);
    return 0;
}

#include <iostream>
#include <chrono>
#include <vector>

int main() {
    const int N = 1000;
    std::vector<std::vector<int>> mat(N, std::vector<int>(N, 1));

    // Row-wise access (good locality)
    auto start = std::chrono::high_resolution_clock::now();
    long sum = 0;
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            sum += mat[i][j];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Row-wise time: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";

    // Column-wise access (poor locality)
    start = std::chrono::high_resolution_clock::now();
    sum = 0;
    for(int j = 0; j < N; j++) {
        for(int i = 0; i < N; i++) {
            sum += mat[i][j];
        }
    }
    end = std::chrono::high_resolution_clock::now();
    std::cout << "Column-wise time: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";

    return 0;
}

