int main() {
    const std::string filename = "test.dat";
    const size_t size = 1024 * 1024; // 1MB
    std::vector<char> buffer(size);

    // Sequential write
    auto start = std::chrono::high_resolution_clock::now();
    std::ofstream out(filename, std::ios::binary);
    out.write(buffer.data(), size);
    out.close();
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Sequential write time: " << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms\n";

    // Random read
    std::ifstream in(filename, std::ios::binary);
    std::mt19937 rng(42);
    std::uniform_int_distribution<size_t> dist(0, size - 1024);
    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < 1000; ++i) {
        size_t pos = dist(rng);
        in.seekg(pos);
        in.read(buffer.data(), 1024);
    }
    in.close();
    end = std::chrono::high_resolution_clock::now();
    std::cout << "Random read time (1000 ops): " << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms\n";

    return 0;
}

