#include <iostream>
#include <chrono>
#include <vector>

int main() {
    const int N = 1024;
    std::vector<std::vector<int>> mat(N, std::vector<int>(N, 1));

    // Row-major (good spatial locality)
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            mat[i][j] *= 2;
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto row_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    // Reset
    for (auto& row : mat) for (auto& x : row) x = 1;

    // Column-major (poor spatial locality)
    start = std::chrono::high_resolution_clock::now();
    for (int j = 0; j < N; ++j) {
        for (int i = 0; i < N; ++i) {
            mat[i][j] *= 2;
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto col_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    std::cout << "Row-major: " << row_time << " us\n";
    std::cout << "Column-major: " << col_time << " us\n";
    return 0;
}

