        arr[i] = i;
        sum_seq += arr[i];
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto duration_seq = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    // Random access (poor locality)
    start = std::chrono::high_resolution_clock::now();
    long sum_rand = 0;
    for (int i = 0; i < size; ++i) {
        int idx = dist(rng);
        sum_rand += arr[idx];
    }
    end = std::chrono::high_resolution_clock::now();
    auto duration_rand = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    std::cout << "Sequential time: " << duration_seq.count() << " us\n";
    std::cout << "Random time: " << duration_rand.count() << " us\n";
    std::cout << "Sequential is faster due to cache locality.\n";
    return 0;
