#include <iostream>
#include <chrono>
#include <vector>

int main() {
    const size_t N = 10000000;
    const size_t stride = 1024; // Likely spans cache lines
    std::vector<int> arr(N);

    // Fill array
    for(size_t i = 0; i < N; ++i) arr[i] = i;

    // Sequential access
    auto start = std::chrono::high_resolution_clock::now();
    long long sum_seq = 0;
    for(size_t i = 0; i < N; ++i) sum_seq += arr[i];
    auto end = std::chrono::high_resolution_clock::now();
    auto seq_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    // Strided access (poorer locality)
    start = std::chrono::high_resolution_clock::now();
    long long sum_stride = 0;
    for(size_t i = 0; i < N; i += stride) {
        if (i < N) sum_stride += arr[i];
    }
    end = std::chrono::high_resolution_clock::now();
    auto stride_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    std::cout << "Sequential time: " << seq_time << " us\n";
    std::cout << "Strided time: " << stride_time << " us\n";
    std::cout << "Sequential is faster due to better cache utilization.\n";
    return 0;
}

