using namespace std;

int main() {
    int cache_size = 4; // Number of cache slots
    vector<int> cache(cache_size, -1); // -1 indicates empty slot
    int misses = 0;
    // Accesses to show collision: addresses 0 and 4 map to same slot (index 0)
    vector<int> accesses = {0, 0, 0, 4, 4, 4, 0, 0};
    for(int addr : accesses) {
        int index = addr % cache_size;
        if (cache[index] != addr) {
            cache[index] = addr;
            misses++;
            cout << "Miss for address " << addr << " at index " << index << endl;
        } else {
            cout << "Hit for address " << addr << " at index " << index << endl;
        }
    }
    cout << "Total misses: " << misses << endl;
    return 0;
}

