    std::cout << "Row-major time: " << time1.count() << "s" << std::endl;

    // Column-major access (poor spatial locality)
    start = std::chrono::high_resolution_clock::now();
    int sum2 = 0;
    for(int j = 0; j < N; ++j) {
        for(int i = 0; i < N; ++i) {
            sum2 += mat[i][j];
        }
    }
    end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> time2 = end - start;
    std::cout << "Column-major time: " << time2.count() << "s" << std::endl;

