    auto duration_mult = std::chrono::duration_cast<std::chrono::microseconds>(end_mult - start_mult);
    auto duration_shift = std::chrono::duration_cast<std::chrono::microseconds>(end_shift - start_shift);

    std::cout << "Multiplication time: " << duration_mult.count() << " us\n";
    std::cout << "Shift time: " << duration_shift.count() << " us\n";
    std::cout << "Sums equal: " << (sum_mult == sum_shift) << std::endl;

