#include <iostream>
#include <chrono>

int main() {
    const int size = 1024;
    int* arr1 = new int[size];
    int* arr2 = new int[size]; // Likely map to same cache lines if aligned poorly

    // Sequential access (good locality)
    auto start1 = std::chrono::high_resolution_clock::now();
    for(int i = 0; i < size; ++i) arr1[i] = i;
    auto end1 = std::chrono::high_resolution_clock::now();
    auto time1 = std::chrono::duration_cast<std::chrono::microseconds>(end1 - start1).count();

    // Interleaved access (potential collisions)
    auto start2 = std::chrono::high_resolution_clock::now();
    for(int i = 0; i < size; ++i) {
        arr1[i] = i;
        arr2[i] = i * 2; // Alternating accesses may cause cache thrashing
    }
    auto end2 = std::chrono::high_resolution_clock::now();
    auto time2 = std::chrono::duration_cast<std::chrono::microseconds>(end2 - start2).count();

    std::cout << "Sequential time: " << time1 << " us\n";
    std::cout << "Interleaved time: " << time2 << " us\n";
    // Interleaved often slower due to direct-mapped cache conflicts

    delete[] arr1;
    delete[] arr2;
    return 0;
}

