#include <iostream>
#include <chrono>
#include <vector>

int main() {
    const int N = 1000000;
    std::vector<int> arr(N);

    // Sequential access (cache-friendly)
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < N; ++i) {
        arr[i] = i;
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto seq_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    // Strided access (cache-unfriendly, simulates poor locality)
    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < 1000; ++i) {
        for (int j = 0; j < 1000; ++j) {
            arr[j * 1000 + i] = i;
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto stride_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    std::cout << "Sequential access time: " << seq_time << " us\n";
    std::cout << "Strided access time: " << stride_time << " us\n";
    // Strided is typically slower due to cache misses
    return 0;
}

