#include <immintrin.h>
#include <iostream>

int main() {
    float a[4] = {1.0f, 2.0f, 3.0f, 4.0f};
    float b[4] = {5.0f, 6.0f, 7.0f, 8.0f};
    float c[4];

    // Scalar addition
    for (int i = 0; i < 4; ++i) {
        c[i] = a[i] + b[i];
    }

    // SIMD addition using SSE
    __m128 va = _mm_loadu_ps(a);
    __m128 vb = _mm_loadu_ps(b);
    __m128 vc = _mm_add_ps(va, vb);
    _mm_storeu_ps(c, vc);

    // Output (should be 6 8 10 12)
    for (int i = 0; i < 4; ++i) {
        std::cout << c[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

