    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < SIZE; ++i) {
        for (int j = 0; j < SIZE; ++j) {
            data[i * SIZE + j] = i + j;
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto row_time = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    // Column-major access (poor cache locality, more misses)
    start = std::chrono::high_resolution_clock::now();
    for (int j = 0; j < SIZE; ++j) {
        for (int i = 0; i < SIZE; ++i) {
            data[j * SIZE + i] = i + j;
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto col_time = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    std::cout << "Row-major: " << row_time << " ms\n";
    std::cout << "Column-major: " << col_time << " ms\n";
    return 0;
}

#include <iostream>
#include <chrono>

long long fact_rec(int n) {
    if (n <= 1) return 1;
    return n * fact_rec(n - 1);
}

long long fact_iter(int n) {
    long long res = 1;
    for (int i = 1; i <= n; ++i) res *= i;
    return res;
}

int main() {
    int n = 20;
    auto start = std::chrono::high_resolution_clock::now();
    fact_rec(n);
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Recursive time: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";

    start = std::chrono::high_resolution_clock::now();
    fact_iter(n);
    end = std::chrono::high_resolution_clock::now();
    std::cout << "Iterative time: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";
    return 0;
}

