#include <numeric>

int main() {
    const size_t N = 10000000;
    std::vector<int> v(N);
    std::iota(v.begin(), v.end(), 0);

    // Sequential access (good locality)
    auto start = std::chrono::high_resolution_clock::now();
    long sum = 0;
    for(size_t i = 0; i < N; ++i) {
        sum += v[i];
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> seq_time = end - start;
    std::cout << "Sequential time: " << seq_time.count() << " s, sum: " << sum << std::endl;

    // Strided access (poor locality)
    start = std::chrono::high_resolution_clock::now();
    sum = 0;
    for(size_t i = 0; i < N; i += 1024) {  // Stride to simulate cache misses
        sum += v[i % N];
    }
    end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> stride_time = end - start;
    std::cout << "Strided time: " << stride_time.count() << " s, sum: " << sum << std::endl;

    return 0;
}

