#include <iostream>

int main() {
    int result = 0;
    // Non-optimized: data hazard (load-use dependency on %eax)
    asm volatile(
        "movl $10, %%eax\n"
        "addl $5, %%eax\n"
        "movl %%eax, %0"
        : "=r" (result)
        :
        : "eax"
    );
    std::cout << "Non-optimized result: " << result << std::endl;

    result = 0;
    // Optimized: reorder to allow parallel execution (e.g., out-of-order CPU can handle)
    asm volatile(
        "movl $10, %%eax\n"
        "movl $5, %%ebx\n"
        "addl %%ebx, %%eax\n"
        "movl %%eax, %0"
        : "=r" (result)
        :
        : "eax", "ebx"
    );
    std::cout << "Optimized result: " << result << std::endl;
    return 0;
}

