#include <iostream>
#include <chrono>

void branched(bool cond, int x, int y) {
    int result;
    if (cond) {
        result = x;
    } else {
        result = y;
    }
    (void)result; // Prevent optimization
}

int branchless(bool cond, int x, int y) {
    return cond ? x : y;
}

int main() {
    const int N = 100000000;
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < N; ++i) {
        branched(i % 2 == 0, 1, 2);
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Branched time: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";

    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < N; ++i) {
        (void)branchless(i % 2 == 0, 1, 2);
    }
    end = std::chrono::high_resolution_clock::now();
    std::cout << "Branchless time: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";
    return 0;
}

