#include <iostream>
#include <chrono>

int main() {
    const int N = 500; // Smaller for brevity
    int arr[N][N];
    // Initialize
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            arr[i][j] = i * N + j;
        }
    }
    // Row-major (cache-friendly, fast)
    auto start = std::chrono::high_resolution_clock::now();
    long sum1 = 0;
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            sum1 += arr[i][j];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto duration1 = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
    // Column-major (cache-unfriendly, slow)
    start = std::chrono::high_resolution_clock::now();
    long sum2 = 0;
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            sum2 += arr[j][i];
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto duration2 = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
    std::cout << "Row-major time: " << duration1.count() << " us\n";
    std::cout << "Column-major time: " << duration2.count() << " us\n";
    return 0;
}

