        std::ifstream in("test.dat", std::ios::binary);
        for (int i = 0; i < 10000; ++i) {
            size_t pos = dis(gen);
            in.seekg(pos);
            char c;
            in.get(c);
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto rand_time = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
