#include <vector>

int main() {
    const int N = 1000;
    std::vector<std::vector<int>> matrix(N, std::vector<int>(N, 1));

    // Row-major access (cache-friendly)
    auto start = std::chrono::high_resolution_clock::now();
    long sum_row = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            sum_row += matrix[i][j];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto duration_row = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    // Column-major access (cache-unfriendly)
    start = std::chrono::high_resolution_clock::now();
    long sum_col = 0;
    for (int j = 0; j < N; ++j) {
        for (int i = 0; i < N; ++i) {
            sum_col += matrix[i][j];
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto duration_col = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    std::cout << "Row-major time: " << duration_row.count() << " us\n";
    std::cout << "Column-major time: " << duration_col.count() << " us\n";
    // Row-major should be faster due to spatial locality and caching.
    return 0;
}

