using namespace std;

class SegregatedAllocator {
    vector<list<void*>> free_lists; // Size classes: 0:<32, 1:32-64, 2:>64
public:
    SegregatedAllocator() : free_lists(3) {
        // Pre-allocate dummy blocks for demo
        free_lists[0].push_back(new char[16]);
        free_lists[1].push_back(new char[48]);
    }
    void* allocate(size_t size) {
        int cls = (size > 64) ? 2 : (size > 32 ? 1 : 0);
        if (!free_lists[cls].empty()) {
            void* ptr = free_lists[cls].front(); free_lists[cls].pop_front();
            return ptr;
        }
        return nullptr; // Simplified
    }
    void deallocate(void* ptr, size_t size) {
        int cls = (size > 64) ? 2 : (size > 32 ? 1 : 0);
        free_lists[cls].push_front(ptr);
    }
    ~SegregatedAllocator() { /* Cleanup omitted for brevity */ }
};

int main() {
    SegregatedAllocator alloc;
    void* p1 = alloc.allocate(20);
    void* p2 = alloc.allocate(50);
    alloc.deallocate(p1, 20);
    alloc.deallocate(p2, 50);
    cout << "Demonstrated segregated allocation by size class." << endl;
    return 0;
}

