#include <iostream>
#include <chrono>
#include <vector>
#include <random>

int main() {
    const int size = 1000000;
    std::vector<int> arr(size, 1);

    // Sequential access (good spatial locality)
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < size; ++i) {
        arr[i] *= 2;
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto seq_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    // Random access (poor locality, more cache misses)
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, size - 1);
    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < size; ++i) {
        int idx = dis(gen);
        arr[idx] *= 2;
    }
    end = std::chrono::high_resolution_clock::now();
    auto rand_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    std::cout << "Sequential time: " << seq_time.count() << " us\n";
    std::cout << "Random time: " << rand_time.count() << " us\n";
    return 0;
}

