#include <iostream>
#include <vector>
#include <chrono>
#include <random>

int main() {
    const size_t size = 1000000;
    std::vector<int> data(size, 1);
    auto start = std::chrono::high_resolution_clock::now();

    // Sequential access (good spatial locality)
    for (size_t i = 0; i < size; ++i) {
        data[i] += 1;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto seq_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    start = std::chrono::high_resolution_clock::now();

    // Random access (poor locality)
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, size - 1);
    for (size_t i = 0; i < size; ++i) {
        data[dis(gen)] += 1;
    }

    end = std::chrono::high_resolution_clock::now();
    auto rand_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    std::cout << "Sequential access time: " << seq_time << " us\n";
    std::cout << "Random access time: " << rand_time << " us\n";
    // Sequential should be faster due to cache locality
    return 0;
}

#include <iostream>
#include <chrono>
#include <vector>

int main() {
    const size_t rows = 100;
    const size_t cols = 100000;
    std::vector<double> mat(rows * cols, 1.0);
    double sum = 0.0;

    // Row-major access (good locality)
    auto start = std::chrono::high_resolution_clock::now();
    for(size_t j = 0; j < rows; ++j) {
        for(size_t i = 0; i < cols; ++i) {
            sum += mat[j * cols + i];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto row_time = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
    std::cout << "Row-major time: " << row_time << " ms" << std::endl;

    // Column-major access (poor locality)
    start = std::chrono::high_resolution_clock::now();
    sum = 0.0;
    for(size_t i = 0; i < cols; ++i) {
        for(size_t j = 0; j < rows; ++j) {
            sum += mat[j * cols + i];
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto col_time = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
    std::cout << "Column-major time: " << col_time << " ms" << std::endl;

    return 0;
}

