        "movl 8(%0), %%ebx;" // base + offset
        "leal (%0, %1, 4), %%ecx;" // base + index * scale (ptr + index*4)
        "movl (%%rcx), %%edx;" // load from computed address
        : "=r"(ptr), "r"(index)
        :
        : "eax", "ebx", "ecx", "edx"
    );

