#include <iostream>

// utils.cpp (compiled separately)
void greet() {
    std::cout << "Hello from resolved symbol!" << std::endl;
}

// main.cpp (compiled separately)
void greet();  // Declaration: external symbol

int main() {
    greet();  // Call: linker resolves to definition in utils.cpp
    return 0;
}

