#include <dlfcn.h>
#include <iostream>

int main() {
    void* handle = dlopen("libm.so", RTLD_LAZY);
    if (!handle) {
        std::cerr << "Error loading library: " << dlerror() << std::endl;
        return 1;
    }

    double (*sin_func)(double) = reinterpret_cast<double (*)(double)>(dlsym(handle, "sin"));
    if (!sin_func) {
        std::cerr << "Error finding symbol: " << dlerror() << std::endl;
        dlclose(handle);
        return 1;
    }

    std::cout << "sin(0.5) = " << sin_func(0.5) << std::endl;
    dlclose(handle);
    return 0;
}

