#include <stdio.h>

int main() {
    void *handle = dlopen("libm.so.6", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "%s\n", dlerror());
        return 1;
    }
    double (*sin_func)(double) = dlsym(handle, "sin");
    if (!sin_func) {
        fprintf(stderr, "%s\n", dlerror());
        dlclose(handle);
