#include <iostream>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/bin/ls", "ls", "-l", NULL);
        std::cerr << "exec failed" << std::endl;
        return 1;
    } else if (pid > 0) {
        // Parent process
        wait(NULL);
        std::cout << "Child finished" << std::endl;
    } else {
        std::cerr << "fork failed" << std::endl;
    }
    return 0;
}

