#include <iostream>

int countSetBits(unsigned int n) {
    int count = 0;
    while (n) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

int main() {
    unsigned int num = 13; // Binary: 1101, has 3 set bits
    std::cout << "Number of set bits: " << countSetBits(num) << std::endl;
    return 0;
}

