#include <setjmp.h>
#include <cstdio>

jmp_buf env;

void inner() {
    std::printf("In inner function\n");
    longjmp(env, 1);
}

void outer() {
    std::printf("In outer function\n");
    inner();
    std::printf("This won't print\n");
}

int main() {
    if (setjmp(env) == 0) {
        std::printf("In main, calling outer\n");
        outer();
    } else {
        std::printf("Jumped back to main\n");
    }
    return 0;
}

