    if (pid == 0) {
        // Child process
        execl("/bin/ls", "ls", "-l", NULL);
        // If exec fails
        std::cerr << "Exec failed" << std::endl;
        exit(1);
    } else if (pid > 0) {
        // Parent process
        wait(NULL);
        std::cout << "Child process finished." << std::endl;
    } else {
        // Fork error
        std::cerr << "Fork failed" << std::endl;
        return 1;
    }
    return 0;
}

