#include <iostream>

int main() {
    int a = 10;
    int b = 4;
    int c = 2;
    int d = 2;

    // Demonstrates precedence: * and / higher than +, left-to-right associativity for * and /
    // Evaluates as: 10 + ((4 * 2) / 2) = 10 + (8 / 2) = 10 + 4 = 14
    int result1 = a + b * c / d;
    std::cout << "With precedence: " << result1 << std::endl;

    // If + had higher precedence or different associativity, it would be different
    int result2 = (a + b) * c / d;  // 14 * 2 / 2 = 14
    std::cout << "With parens (wrong assumption): " << result2 << std::endl;

    // Associativity example: - is left-to-right
    // 5 - 2 - 3 = (5 - 2) - 3 = 0, not 5 - (2 - 3) = 6
    int e = 5, f = 2, g = 3;
    int result3 = e - f - g;
    std::cout << "Associativity (- left-to-right): " << result3 << std::endl;

    return 0;
}

