class SimpleCPU {
private:
    int regA = 0, pc = 0;
    int memory[4] = {1, 2, 3, 0}; // Simple program: load 1 to A, add 2, store to mem[3]

public:
    void step() {
        int instr = memory[pc++];
        if (instr == 1) regA = memory[pc++];
        else if (instr == 2) regA += memory[pc++];
        else if (instr == 3) memory[pc++] = regA;
    }

    void run() {
        while (pc < 4) step();
        std::cout << "Result in memory[3]: " << memory[3] << std::endl;
    }
};

