#include <iostream>
#include <list>
#include <unordered_map>

using namespace std;

class LRUCache {
private:
    int cap;
    list<pair<int,int>> l;
    unordered_map<int, list<pair<int,int>>::iterator> m;
public:
    LRUCache(int capacity) : cap(capacity) {}
    int get(int key) {
        if (m.find(key) == m.end()) return -1;
        l.splice(l.begin(), l, m[key]);
        return m[key]->second;
    }
    void put(int key, int value) {
        if (m.find(key) != m.end()) {
            l.splice(l.begin(), l, m[key]);
            m[key]->second = value;
            return;
        }
        if (l.size() == cap) {
            int last = l.back().first;
            l.pop_back();
            m.erase(last);
        }
        l.emplace_front(key, value);
        m[key] = l.begin();
    }
};

int main() {
    LRUCache cache(2);
    cache.put(1, 1);
    cache.put(2, 2);
    cout << cache.get(1) << endl; // 1
    cache.put(3, 3);
    cout << cache.get(2) << endl; // -1
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class LRUCache {
    int cap;
    list<int> l;
    unordered_map<int, list<int>::iterator> m;
public:
    LRUCache(int c) : cap(c) {}
    int get(int key) {
        if (m.count(key) == 0) return -1;
        l.splice(l.begin(), l, m[key]);
        return key;
    }
    void put(int key) {
        if (m.count(key)) {
            l.splice(l.begin(), l, m[key]);
        } else {
            if (l.size() == cap) {
                int last = l.back(); l.pop_back(); m.erase(last);
            }
            l.push_front(key); m[key] = l.begin();
        }
    }
};

int main() {
    LRUCache cache(2);
    cache.put(1); cache.put(2);
    cout << cache.get(1) << endl; // 1
    cache.put(3);
    cout << cache.get(2) << endl; // -1
