#include <stdio.h>

#define MAX 5
int queue[MAX];
int front = -1, rear = -1;

void enqueue(int x) {
    if (rear == MAX - 1) return;
    if (front == -1) front = 0;
    queue[++rear] = x;
}

int dequeue() {
    if (front == -1 || front > rear) return -1;
    return queue[front++];
}

int main() {
    enqueue(1); enqueue(2); enqueue(3);
    printf("%d\n", dequeue()); // Outputs 1
    return 0;
}

