#include <iostream>
#include <cstdint>

class Bitmap {
    std::uint32_t bits = 0;
public:
    bool allocate(int index) {
        if (index < 0 || index >= 32) return false;
        std::uint32_t mask = 1u << index;
        if (bits & mask) return false;
        bits |= mask;
        return true;
    }
    bool free(int index) {
        if (index < 0 || index >= 32) return false;
        std::uint32_t mask = 1u << index;
        bits &= ~mask;
        return true;
    }
    bool is_free(int index) const {
        if (index < 0 || index >= 32) return false;
        return !(bits & (1u << index));
    }
};

int main() {
    Bitmap bm;
    std::cout << "Resource 0 free: " << bm.is_free(0) << std::endl;
    bm.allocate(0);
    std::cout << "Resource 0 free: " << bm.is_free(0) << std::endl;
    bm.free(0);
    std::cout << "Resource 0 free: " << bm.is_free(0) << std::endl;
    return 0;
}

