int main() {
    std::vector<int> page_table(4, -1); // Linear page table: -1 invalid
    page_table[0] = 5; // VP 0 -> PF 5
    page_table[1] = 2; // VP 1 -> PF 2

    auto translate = [&](int va) -> int {
        int vpn = va / 1024;
        int offset = va % 1024;
        if (vpn >= 4 || page_table[vpn] == -1) return -1;
        return page_table[vpn] * 1024 + offset;
    };

    std::cout << translate(0) << std::endl;     // 5120
    std::cout << translate(1024) << std::endl;  // 2048
    return 0;
}

