#include <iostream>

class SimpleCPU {
private:
    int reg = 0;
    int pc = 0;
    int memory[10] = {1, 5, 2, 3, 0, 0, 0, 0, 0, 0}; // Instructions: 1=add next, 2=sub next, 0=halt
public:
    void execute() {
        while (true) {
            int instr = memory[pc++];
            if (instr == 0) break;
            int val = memory[pc++];
            if (instr == 1) reg += val;
            else if (instr == 2) reg -= val;
        }
        std::cout << "Result in register: " << reg << std::endl;
    }
};

int main() {
    SimpleCPU cpu;
    cpu.execute();
    return 0;
}

