#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> pages = {7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1};
    int frames = 3;
    list<int> frame_list;
    unordered_map<int, list<int>::iterator> mp;
    int faults = 0;
    for(int page : pages) {
        if(mp.find(page) == mp.end()) {
            if(frame_list.size() == frames) {
                int lru = frame_list.back();
                frame_list.pop_back();
                mp.erase(lru);
            }
            faults++;
        } else {
            frame_list.erase(mp[page]);
        }
        frame_list.push_front(page);
        mp[page] = frame_list.begin();
    }
    cout << "Page faults: " << faults << endl;
    return 0;
}

