#include <stdio.h>
#include <unistd.h>

sem_t sem;
int shared = 0;

void* thread_func(void* arg) {
    int id = *(int*)arg;
    sem_wait(&sem);
    shared += id;
    printf("Thread %d: shared = %d\n", id, shared);
    sem_post(&sem);
    return NULL;
}

int main() {
    sem_init(&sem, 0, 1);
    pthread_t t1, t2;
    int id1 = 1, id2 = -1;
    pthread_create(&t1, NULL, thread_func, &id1);
    pthread_create(&t2, NULL, thread_func, &id2);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    sem_destroy(&sem);
    return 0;
}

