template <typename T>
class SimpleAllocator {
public:
    using value_type = T;
    SimpleAllocator() = default;
    template <typename U> constexpr SimpleAllocator(const SimpleAllocator<U>&) noexcept {}
    T* allocate(size_t n) {
        return static_cast<T*>(::operator new(n * sizeof(T)));
    }
    void deallocate(T* p, size_t) {
        ::operator delete(p);
    }
};

