#include <iostream>
#include <string>

int my_stoi(const std::string& str) {
    int result = 0;
    bool negative = false;
    size_t i = 0;
    if (i < str.size() && str[i] == '-') {
        negative = true;
        ++i;
    }
    for (; i < str.size(); ++i) {
        char c = str[i];
        if (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
        } else {
            break;
        }
    }
    return negative ? -result : result;
}

int main() {
    std::string s = "-123";
    std::cout << my_stoi(s) << std::endl;
    return 0;
}

