class Shape {
public:
    virtual double area() const = 0;
    virtual ~Shape() = default;
};

class Circle : public Shape {
    double r;
public:
    Circle(double r) : r(r) {}
    double area() const override { return 3.14 * r * r; }
};

class Rectangle : public Shape {
    double w, h;
public:
    Rectangle(double w, double h) : w(w), h(h) {}
    double area() const override { return w * h; }
};

using VarShape = std::variant<Circle, Rectangle>;

double var_area(const VarShape& s) {
    return std::visit([](const auto& shape) { return shape.area(); }, s);
}

int main() {
    auto rt = std::make_unique<Circle>(1.0);
    std::cout << "Runtime: " << rt->area() << std::endl;

    VarShape vt(1.0); // Circle(1.0)
    std::cout << "Variant: " << var_area(vt) << std::endl;

    return 0;
}

