public:
    HasResource(int val) : ptr(new int(val)) {
        std::cout << "Constructed with " << *ptr << std::endl;
    }
    HasResource(const HasResource& other) : ptr(new int(*other.ptr)) {
        std::cout << "Copied" << std::endl;
    }
    HasResource(HasResource&& other) : ptr(other.ptr) {
        other.ptr = nullptr;
        std::cout << "Moved" << std::endl;
    }
    ~HasResource() {
        if (ptr) {
            std::cout << "Destroyed " << *ptr << std::endl;
            delete ptr;
        } else {
            std::cout << "Destroyed null" << std::endl;
        }
    }
    int get() const { return ptr ? *ptr : 0; }
};

