class Vec {
    double* data;
    size_t size;
public:
    Vec(size_t s) : size(s), data(new double[s]) {}
    ~Vec() { delete[] data; }
    double& operator[](size_t i) { return data[i]; }
    const double& operator[](size_t i) const { return data[i]; }
    template <typename Expr>
    Vec& operator=(const Expr& e) {
        for(size_t i = 0; i < size; ++i) data[i] = e[i];
        return *this;
    }
};

template <typename L, typename R>
class AddExpr {
    const L& left; const R& right;
public:
    AddExpr(const L& l, const R& r) : left(l), right(r) {}
    double operator[](size_t i) const { return left[i] + right[i]; }
};

template <typename L, typename R>
AddExpr<L, R> operator+(const L& l, const R& r) { return {l, r}; }

int main() {
    Vec a(2), b(2);
    a[0] = 1; a[1] = 2;
    b[0] = 3; b[1] = 4;
    Vec c(2);
    c = a + b;  // Deferred evaluation via expression template
    std::cout << c[0] << " " << c[1] << std::endl;  // Outputs: 4 6
    return 0;
}

