#include <iostream>

void sideEffect() {
    std::cout << "Right operand evaluated!\n";
}

int main() {
    // Left is true, so right is not evaluated
    if (true || sideEffect()) {
        std::cout << "Condition is true (short-circuit).\n";
    }

    // Left is false, so right is evaluated
    if (false || sideEffect()) {
        std::cout << "Condition is true (right evaluated).\n";
    }

    return 0;
}

#include <iostream>

class Resource {
private:
    int* data;
public:
    Resource(int val) : data(new int(val)) {
        std::cout << "Constructed with value " << val << std::endl;
    }
    Resource(const Resource& other) : data(new int(*other.data)) {
        std::cout << "Copied" << std::endl;
    }
    Resource(Resource&& other) noexcept : data(other.data) {
        other.data = nullptr;
        std::cout << "Moved" << std::endl;
    }
    ~Resource() { delete data; }
    int get() const { return data ? *data : 0; }
};

int main() {
    Resource a(10);
    Resource b = a;        // Copy
    Resource c = Resource(20); // Move from temporary
    std::cout << "a: " << a.get() << ", b: " << b.get() << ", c: " << c.get() << std::endl;
    return 0;
}

