#include <iostream>

class LocaleFacet {
public:
    template <typename CharT>
    int compare(const CharT* low1, const CharT* high1,
                const CharT* low2, const CharT* high2) const {
        while (low1 < high1 && low2 < high2) {
            if (*low1 != *low2) return *low1 < *low2 ? -1 : 1;
            ++low1; ++low2;
        }
        if (low1 == high1) return (low2 == high2) ? 0 : -1;
        return 1;
    }
};

int main() {
    LocaleFacet f;
    const char* ca = "abc";
    const wchar_t* wa = L"abc";
    std::cout << f.compare(ca, ca + 3, ca, ca + 3) << std::endl; // 0
    std::cout << f.compare(wa, wa + 3, wa, wa + 3) << std::endl; // 0
