    mtx.lock();  // Main thread holds the lock

    std::thread t([&mtx]() {
        if (mtx.try_lock_for(std::chrono::milliseconds(50))) {
            std::cout << "Lock acquired within timeout\n";
            mtx.unlock();
        } else {
            std::cout << "Lock acquisition timed out\n";
        }
