        advance_impl(steps, Tag{});
    }
private:
    void advance_impl(int steps, input_iterator_tag) {
        std::cout << "Input: loop " << steps << " times\n";
    }
    void advance_impl(int steps, bidirectional_iterator_tag) {
        std::cout << "Bidirectional: ++ or -- " << steps << " times\n";
    }
};

