#include <iostream>
#include <variant>

// Runtime polymorphism
struct Base {
    virtual void speak() = 0;
    virtual ~Base() = default;
};
struct Dog : Base {
    void speak() override { std::cout << "Woof!\n"; }
};
struct Cat : Base {
    void speak() override { std::cout << "Meow!\n"; }
};

// Compile-time polymorphism with std::variant
struct Dog2 {
    void speak() { std::cout << "Woof!\n"; }
};
struct Cat2 {
    void speak() { std::cout << "Meow!\n"; }
};
using Var = std::variant<Dog2, Cat2>;
struct Visitor {
    void operator()(Dog2& d) { d.speak(); }
    void operator()(Cat2& c) { c.speak(); }
};

int main() {
    // Runtime
    Base* b = new Dog();
    b->speak();
    delete b;

    // Compile-time
    Var v = Dog2{};
    std::visit(Visitor{}, v);
    return 0;
}

