#include <mutex>
#include <iostream>

int main() {
    std::mutex mtx;

    // Normal lock (implicitly uses std::adopt_lock or default)
    {
        std::unique_lock<std::mutex> lock1(mtx);
        std::cout << "Normal lock acquired.\n";
    }

    // Defer lock
    {
        std::unique_lock<std::mutex> lock2(mtx, std::defer_lock);
        lock2.lock();
        std::cout << "Deferred lock acquired.\n";
    }

    // Try to lock
    {
        std::unique_lock<std::mutex> lock3(mtx, std::try_to_lock);
        if (lock3.owns_lock()) {
            std::cout << "Try lock succeeded.\n";
        } else {
            std::cout << "Try lock failed.\n";
        }
    }

    return 0;
}

