#include <iostream>

class NonCopyable {
public:
    NonCopyable() = default;  // Defaulted constructor
    ~NonCopyable() = default;  // Defaulted destructor
    NonCopyable(const NonCopyable&) = delete;  // Deleted copy constructor
    NonCopyable& operator=(const NonCopyable&) = delete;  // Deleted copy assignment
    NonCopyable(NonCopyable&&) = default;  // Defaulted move constructor
    NonCopyable& operator=(NonCopyable&&) = default;  // Defaulted move assignment
};

int main() {
    NonCopyable obj1;
