#include <shared_mutex>
#include <thread>
#include <chrono>
#include <iostream>

int main() {
    std::shared_timed_mutex mtx;

    // Reader 1: Shared lock with timeout
    std::thread reader1([&mtx] {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(100);
        if (mtx.try_lock_shared_until(deadline)) {
            std::cout << "Reader 1: Acquired shared lock\n";
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            mtx.unlock_shared();
        } else {
            std::cout << "Reader 1: Timeout\n";
        }
    });

    // Reader 2: Shared lock (non-timed for comparison)
    std::thread reader2([&mtx] {
        mtx.lock_shared();
        std::cout << "Reader 2: Acquired shared lock\n";
        std::this_thread::sleep_for(std::chrono::milliseconds(150));
        mtx.unlock_shared();
    });

    // Writer: Exclusive lock
    std::thread writer([&mtx] {
        std::this_thread::sleep_for(std::chrono::milliseconds(200)); // Delay to allow readers
        mtx.lock();
        std::cout << "Writer: Acquired exclusive lock\n";
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        mtx.unlock();
    });

    reader1.join();
    reader2.join();
    writer.join();
    return 0;
}

