#include <memory>
#include <atomic>
#include <thread>
#include <iostream>

int main() {
    std::atomic<std::shared_ptr<int>> ptr;
    auto sp1 = std::make_shared<int>(42);
    ptr.store(sp1);

    std::thread t1([&] {
        auto sp2 = std::make_shared<int>(100);
        auto old = ptr.exchange(sp2, std::memory_order_seq_cst);
        std::cout << "Exchanged: " << *old << " -> " << *sp2 << std::endl;
    });

    t1.join();
    std::cout << "Final value: " << *ptr.load() << std::endl;
    return 0;
}

