// Function template
 template <typename T>
 void swap(T& a, T& b) {
     T temp = a;
     a = b;
     b = temp;
 }

// Class template
 template <typename T>
 class Box {
 private:
     T value;
 public:
     Box(T v) : value(v) {}
     T get() const { return value; }
     void set(T v) { value = v; }
 };

int main() {
     int x = 5, y = 10;
     std::cout << "Before swap: " << x << " " << y << std::endl;
     swap(x, y);
     std::cout << "After swap: " << x << " " << y << std::endl;

     Box<int> intBox(42);
     std::cout << "Int box: " << intBox.get() << std::endl;

     Box<double> doubleBox(3.14);
     std::cout << "Double box: " << doubleBox.get() << std::endl;

     return 0;
 }

