// SFINAE trait to detect if T has to_string()
template <typename T>
struct has_to_string {
private:
    template <typename U> static auto test(int) -> decltype(std::declval<U>().to_string(), std::true_type{});
    template <typename> static std::false_type test(...);
public:
    static constexpr bool value = decltype(test<T>(0))::value;
};

// Class template with partial specialization based on SFINAE trait
template <typename T, bool B = has_to_string<T>::value>
struct Printer;

template <typename T>
struct Printer<T, true> {
    static void print(const T& t) { t.to_string(); std::cout << " (custom)" << std::endl; }
};

template <typename T>
struct Printer<T, false> {
    static void print(const T& t) { std::cout << "Default" << std::endl; }
};

struct A { void to_string() { std::cout << "A"; } };
struct B {};

int main() {
    Printer<A>::print(A{});
    Printer<B>::print(B{});
    return 0;
}

#include <iostream>

template <typename Iterator>
class reverse_iterator {
public:
    Iterator current;
    reverse_iterator(Iterator it) : current(it) {}
    Iterator base() const { return current; }
};

template <typename T, typename U>
bool operator>(const reverse_iterator<T>& a, const reverse_iterator<U>& b) {
    return b.base() < a.base();
}

int main() {
    int arr[2] = {1, 2};
    reverse_iterator<int*> ri1(arr + 1);
    reverse_iterator<int*> ri2(arr + 0);
    std::cout << (ri1 > ri2) << std::endl;  // Outputs 1 (true)
    return 0;
}

