#include <iostream>
#include <vector>

// Simple predicate function
bool is_equal(int a, int b) { return a == b; }

// Function template with predicate parameter
template<typename Iter, typename Pred>
Iter adjacent_find(Iter first, Iter last, Pred pred) {
    while (first != last - 1) {
        if (pred(*first, *(first + 1))) return first;
        ++first;
    }
    return last;
}

int main() {
    std::vector<int> vec = {1, 2, 2, 3, 4};
    auto it = adjacent_find(vec.begin(), vec.end(), is_equal);
    if (it != vec.end()) {
        std::cout << "Found at position: " << (it - vec.begin()) << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }
    return 0;
}

