    // Insert elements to trigger rehashing
    for (int i = 1; i <= 20; ++i) {
        m["key" + std::to_string(i)] = i;
    }

    // it is now invalidated due to rehashing
    // std::cout << it->second << std::endl; // Undefined Behavior!
