// Function template with multiple parameters: Iter and Pred
// Type deduction happens on call

template<typename Iter, typename Pred>
Iter my_find(Iter begin, Iter end, Pred pred) {
    for (; begin != end; ++begin) {
        if (pred(*begin)) {
            return begin;
        }
    }
    return end;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5};
    auto it = my_find(vec.begin(), vec.end(), [](int x) { return x > 3; });
    if (it != vec.end()) {
        std::cout << "Found: " << *it << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }
    return 0;
}

