        std::cout << "Acquired lock with seconds duration" << std::endl;
        mtx.unlock();
    } else {
        std::cout << "Failed to acquire lock with seconds" << std::endl;
    }
    if (mtx.try_lock_for(std::chrono::milliseconds(500))) {
        std::cout << "Acquired lock with milliseconds duration" << std::endl;
