#include <atomic>
#include <thread>
#include <iostream>

int y = 0;
std::atomic<int> x(0);

void thread1() {
    y = 1;
    std::atomic_store_explicit(&x, 1, std::memory_order_release);
}

void thread2() {
    int r = x.load(std::memory_order_acquire);
    if (r == 1) {
        std::cout << "y is " << y << std::endl;  // Expected: 1 due to ordering
    }
}

int main() {
    std::thread t1(thread1);
    std::thread t2(thread2);
    t1.join();
    t2.join();
    return 0;
}

