#include <iostream>
#include <utility>
#include <string>

class CustomStream {
private:
    std::string buffer;
public:
    CustomStream() = default;
    CustomStream(CustomStream&& other) noexcept : buffer(std::move(other.buffer)) {
        std::cout << "Move constructor called\n";
    }
    // Perfect forwarding for appending arguments
    template<typename... Args>
    CustomStream& append(Args&&... args) {
        (buffer.append(std::forward<Args>(args)), ...);
        return *this;
    }
    void print() const { std::cout << buffer << '\n'; }
};

int main() {
    std::string temp = "world";
    CustomStream stream;
    stream.append("Hello, ", std::move(temp), "!"); // Mix lvalue/rvalue
    stream.print(); // Output: Hello, world!
    return 0;
}

