struct Foo {
    Foo() { std::cout << "Foo created\n"; }
    ~Foo() { std::cout << "Foo destroyed\n"; }
};

int main() {
    // unique_ptr: exclusive ownership
    std::unique_ptr<Foo> up1 = std::make_unique<Foo>();
    {
        auto up2 = std::move(up1);  // Transfer ownership
    }  // up2 destroys Foo

    // shared_ptr: shared ownership
    std::shared_ptr<Foo> sp1 = std::make_shared<Foo>();
    {
        auto sp2 = sp1;  // Share ownership
        std::cout << "Ref count: " << sp2.use_count() << "\n";
    }  // sp2 dies, ref count drops
    std::cout << "Ref count: " << sp1.use_count() << "\n";
    // sp1 destroys Foo
    return 0;
}

