class Resource {
private:
    int* data;
    size_t size;
public:
    Resource(size_t s) : size(s), data(new int[s]) {
        std::fill(data, data + size, 42);
    }
    Resource(const Resource& other) : size(other.size), data(new int[other.size]) {
        std::copy(other.data, other.data + size, data);
        std::cout << "Copy constructor called\n";
    }
    Resource(Resource&& other) noexcept : size(other.size), data(other.data) {
        other.data = nullptr;
        other.size = 0;
        std::cout << "Move constructor called\n";
    }
    ~Resource() { delete[] data; }
    void print() const {
        if (data) std::cout << "Size: " << size << "\n";
        else std::cout << "Empty\n";
    }
};

int main() {
    Resource r1(5);
    std::cout << "Original:\n";
    r1.print();
    Resource r2 = std::move(r1);
    std::cout << "After move:\n";
    r1.print();  // Empty
    r2.print();  // Has data
