    Movable(int v) : val(v) { std::cout << "constructed with " << v << std::endl; }
    Movable(const Movable& other) : val(other.val) { std::cout << "copy constructed" << std::endl; }
    Movable(Movable&& other) : val(other.val) { std::cout << "move constructed" << std::endl; }
};

template <typename T>
class Wrapper {
    T obj;
public:
    template <typename U>
    Wrapper(U&& u) : obj(std::forward<U>(u)) {}
};

int main() {
    Movable m(42);
    std::cout << "Creating with lvalue:" << std::endl;
    Wrapper<Movable> w1(m);  // copy
    std::cout << "\nCreating with rvalue:" << std::endl;
    Wrapper<Movable> w2(Movable(43));  // move
    return 0;
}

