// Simple function template with predicate parameter

template<typename T, typename Predicate>
bool hasAdjacentPair(const T* arr, size_t size, Predicate pred) {
    for (size_t i = 0; i < size - 1; ++i) {
        if (pred(arr[i], arr[i + 1])) {
            return true;
        }
    }
    return false;
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    auto isSumFive = [](int a, int b) { return a + b == 5; };
    std::cout << std::boolalpha << hasAdjacentPair(arr, 5, isSumFive) << std::endl;
    // Output: true (2+3==5)
    return 0;
}

