    display(*ptr);  // Generic for double
    display(ptr);   // Specialized
    std::unique_ptr<Point> pPtr(new Point(1, 1));
    Point p2(3, 4);
    std::cout << *pPtr + p2 << std::endl;  // Uses overloaded operator+
    return 0;
}

