#include <iostream>
#include <string>

class Resource {
private:
    std::string* data;
public:
    Resource() : data(new std::string("original")) {}
    Resource(const std::string& s) : data(new std::string(s)) {}

    // Move constructor
    Resource(Resource&& other) noexcept : data(other.data) {
        other.data = nullptr;
    }

    // Move assignment operator
    Resource& operator=(Resource&& other) noexcept {
        if (this != &other) {
            delete data;
            data = other.data;
            other.data = nullptr;
        }
        return *this;
    }

    ~Resource() { delete data; }

    void print() const {
        if (data) std::cout << *data << std::endl;
    }
};

int main() {
    Resource obj;
    obj = Resource("moved from rvalue");  // Demonstrates move assignment
    obj.print();
    return 0;
}

