// Primary template for general types
 template <typename T>
struct SetOperations {
    static void printUnion(const std::vector<T>& a, const std::vector<T>& b) {
        std::vector<T> result;
        std::set_union(a.begin(), a.end(), b.begin(), b.end(), std::back_inserter(result));
        for (const auto& x : result) std::cout << x << " ";
        std::cout << std::endl;
    }
};

// Specialization for int (using set for simplicity, different from linear merge)
template <>
struct SetOperations<int> {
    static void printUnion(const std::vector<int>& a, const std::vector<int>& b) {
        std::set<int> s(a.begin(), a.end());
        for (int x : b) s.insert(x);
        for (int x : s) std::cout << x << " ";
        std::cout << std::endl;
    }
};

int main() {
    std::vector<int> v1 = {1, 3, 5};
    std::vector<int> v2 = {2, 4, 5};
    SetOperations<int>::printUnion(v1, v2);  // Uses specialization

    std::vector<double> d1 = {1.1, 2.2};
    std::vector<double> d2 = {2.2, 3.3};
    SetOperations<double>::printUnion(d1, d2);  // Uses primary
    return 0;
}

