#include <iostream>

// Simple function template with predicate

template <typename T, typename Pred>
T* adjacent_find(T* first, T* last, Pred p) {
    while (first != last - 1) {
        if (p(*first, *(first + 1))) {
            return first;
        }
        ++first;
    }
    return last;
}

int main() {
    int arr[] = {1, 3, 2, 2, 4};
    auto pred = [](int a, int b) { return a == b; };
    int* it = adjacent_find(arr, arr + 5, pred);
    std::cout << (it != arr + 5 ? "Found adjacent equal elements" : "No adjacent equals") << std::endl;
    return 0;
}

