#include <iostream>

struct input_tag {};
struct forward_tag : input_tag {};

template <typename Iter, typename Tag = input_tag>
class Dispatcher {
public:
    void dispatch(Iter it) {
        dispatch_impl(it, Tag{});
    }
private:
    void dispatch_impl(Iter it, input_tag) {
        std::cout << "Input iterator dispatch\n";
    }
    void dispatch_impl(Iter it, forward_tag) {
        std::cout << "Forward iterator dispatch\n";
    }
};

int main() {
    Dispatcher<int*, input_tag> d1;
    d1.dispatch(nullptr);
    Dispatcher<int*, forward_tag> d2;
    d2.dispatch(nullptr);
    Dispatcher<int*> d3;  // Uses default input_tag
    d3.dispatch(nullptr);
    return 0;
}

