#include <iostream>

constexpr int factorial(int n) {
    return n <= 1 ? 1 : n * factorial(n - 1);
}

int runtime_factorial(int n) {
    return n <= 1 ? 1 : n * runtime_factorial(n - 1);
}

int main() {
    constexpr int compile_time = factorial(5);  // Evaluated at compile time
    std::cout << "Compile-time factorial(5): " << compile_time << std::endl;

    int rt = runtime_factorial(5);  // Evaluated at runtime
    std::cout << "Runtime factorial(5): " << rt << std::endl;

    return 0;
}

