#include <iostream>
#include <shared_mutex>
#include <thread>
#include <chrono>

int main() {
    std::shared_timed_mutex smtx;

    std::thread writer([&smtx] {
        smtx.lock();
        std::cout << "Writer locked exclusively." << std::endl;
        std::this_thread::sleep_for(std::chrono::seconds(2));
        smtx.unlock();
        std::cout << "Writer unlocked." << std::endl;
    });

    std::this_thread::sleep_for(std::chrono::milliseconds(100));

    auto start = std::chrono::steady_clock::now();
    bool locked = smtx.try_lock_shared_for(std::chrono::seconds(1));
    auto end = std::chrono::steady_clock::now();

    std::cout << "Tried to lock shared for 1s: " << (locked ? "success" : "timeout") << std::endl;
    std::cout << "Waited for: " << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms" << std::endl;

    if (locked) smtx.unlock_shared();

    writer.join();
    return 0;
}

