#include <shared_mutex>
#include <thread>
#include <chrono>
#include <iostream>

int main() {
    std::shared_timed_mutex mtx;

    std::thread reader1([&]() {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(1);
        if (mtx.try_lock_shared_until(deadline)) {
            std::cout << "Reader 1: shared lock acquired\n";
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
            mtx.unlock_shared();
        } else {
            std::cout << "Reader 1: timeout\n";
        }
    });

    std::thread reader2([&]() {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(1);
        if (mtx.try_lock_shared_until(deadline)) {
            std::cout << "Reader 2: shared lock acquired\n";
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
            mtx.unlock_shared();
        } else {
            std::cout << "Reader 2: timeout\n";
        }
    });

    std::thread writer([&]() {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        if (mtx.try_lock_until(deadline)) {
            std::cout << "Writer: exclusive lock acquired\n";
            std::this_thread::sleep_for(std::chrono::seconds(1));
            mtx.unlock();
        } else {
            std::cout << "Writer: timeout\n";
        }
    });

    reader1.join();
    reader2.join();
    writer.join();
    return 0;
}

