#include <iostream>
#include <shared_mutex>
#include <thread>
#include <chrono>

int main() {
    std::shared_timed_mutex mtx;

    std::thread writer([&mtx] {
        std::this_thread::sleep_for(std::chrono::seconds(1));
        mtx.lock();
        std::cout << "Writer acquired exclusive lock\n";
        std::this_thread::sleep_for(std::chrono::seconds(2));
        mtx.unlock();
        std::cout << "Writer released lock\n";
    });

    std::thread reader([&mtx] {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(3);
        if (mtx.try_lock_shared_until(deadline)) {
            std::cout << "Reader acquired shared lock\n";
            std::this_thread::sleep_for(std::chrono::seconds(1));
            mtx.unlock_shared();
            std::cout << "Reader released lock\n";
        } else {
            std::cout << "Reader timed out\n";
        }
    });

    writer.join();
    reader.join();
    return 0;
}

