#include <mutex>
#include <iostream>

int main() {
    std::mutex mtx;

    // Using defer_lock: no lock in constructor
    std::unique_lock<std::mutex> lock1(mtx, std::defer_lock);
    lock1.lock();  // Manual lock

    // Using try_to_lock: attempt lock, may fail
    std::unique_lock<std::mutex> lock2(mtx, std::try_to_lock);
    if (lock2.owns_lock()) {
        std::cout << "Acquired lock with try_to_lock" << std::endl;
    } else {
        std::cout << "Failed to acquire lock with try_to_lock" << std::endl;
    }

    // Using adopt_lock: assumes already locked (demo with manual lock first)
    mtx.unlock();  // Release for demo
    mtx.lock();    // Manual lock
    std::unique_lock<std::mutex> lock3(mtx, std::adopt_lock);
    std::cout << "Adopted lock" << std::endl;

    return 0;
}

