#include <atomic>
#include <iostream>

int main() {
    std::atomic<int> counter{0};
    int expected = 0;
    int desired = 1;

    // Use compare_exchange_weak with relaxed memory order
    while (!counter.compare_exchange_weak(expected, desired,
                                          std::memory_order_relaxed,
                                          std::memory_order_relaxed)) {
        // Spurious failure loop; update expected and desired
        expected = counter.load(std::memory_order_relaxed);
        desired = expected + 1;
    }

    std::cout << "Counter: " << counter << std::endl;
    return 0;
}

