struct LocaleComparator {
    template <typename CharT>
    int compare(const std::basic_string<CharT>& s1,
                const std::basic_string<CharT>& s2,
                const std::locale& loc) {
        std::collate<CharT>& coll = std::use_facet<std::collate<CharT>>(loc);
        return coll.compare(s1.data(), s1.data() + s1.size(),
                            s2.data(), s2.data() + s2.size());
    }
};

int main() {
    std::locale loc;
    LocaleComparator comp;
    std::string s1 = "abc";
    std::string s2 = "abd";
    int res = comp.compare(s1, s2, loc);
    std::cout << res << std::endl;  // Outputs negative value
    return 0;
}

