#include <iostream>
#include <utility>

class Resource {
private:
    int* data;
    size_t size;
public:
    Resource(size_t s) : size(s), data(new int[s]) {
        std::cout << "Constructed with size " << size << std::endl;
    }
    Resource(const Resource& other) : size(other.size), data(new int[other.size]) {
        std::copy(other.data, other.data + size, data);
        std::cout << "Copied" << std::endl;
    }
    Resource(Resource&& other) noexcept : size(other.size), data(other.data) {
        other.data = nullptr;
        other.size = 0;
        std::cout << "Moved" << std::endl;
    }
    ~Resource() {
        delete[] data;
    }
    void print() { std::cout << "Resource size: " << size << std::endl; }
};

int main() {
