int main() {
    std::string s = "Hello";
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < 10000; ++i) {
        s.insert(0, "World ");  // Insert at beginning (inefficient for large loops)
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = end - start;
    std::cout << "Time: " << elapsed.count() << "s, Size: " << s.size() << std::endl;
    // Alternative efficient insert at end
    std::string s2;
    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < 10000; ++i) {
        s2 += "World ";  // Or s2.insert(s2.end(), "World ");
    }
    end = std::chrono::high_resolution_clock::now();
    elapsed = end - start;
    std::cout << "Efficient time: " << elapsed.count() << "s" << std::endl;
    return 0;
}

