#include <atomic>
#include <thread>
#include <iostream>

std::atomic<int> x(0);
std::atomic<int> y(0);

void producer() {
    x.store(42, std::memory_order_relaxed);
    y.store(1, std::memory_order_release);
}

void consumer() {
    int ry = y.load(std::memory_order_acquire);
    if (ry == 1) {
        std::cout << "x value: " << x.load(std::memory_order_relaxed) << std::endl;
    }
}

