    static constexpr int value = N * Factorial<N - 1>::value;
};

template<>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Use type trait to enable only for integral types
template<typename T>
std::enable_if_t<std::is_integral<T>::value, int> compute_factorial(T n) {
    return Factorial<n>::value;
}

int main() {
    std::cout << compute_factorial(5) << std::endl; // Outputs: 120
    return 0;
}

