class LocaleFacet {
public:
    template<typename CharT>
    int compare(const CharT* s1, const CharT* s2, size_t len) const {
        for(size_t i = 0; i < len; ++i) {
            if(s1[i] < s2[i]) return -1;
            if(s1[i] > s2[i]) return 1;
        }
        return 0;
    }
};

int main() {
    LocaleFacet f;
    std::string a = "abc";
    std::string b = "abd";
    int res = f.compare(a.data(), b.data(), 3);
    std::cout << res << std::endl;  // Outputs -1
    return 0;
}

