#include <vector>

// Custom implementation of adjacent_find

template<typename ForwardIt>
ForwardIt my_adjacent_find(ForwardIt first, ForwardIt last) {
    if (first == last) return last;
    ForwardIt next = first;
    ++next;
    for (; next != last; ++first, ++next) {
        if (*first == *next) {
            return first;
        }
    }
    return last;
}

int main() {
    std::vector<int> v = {1, 2, 2, 3, 4};
    auto it = my_adjacent_find(v.begin(), v.end());
    if (it != v.end()) {
        std::cout << "Found at position: " << (it - v.begin()) << std::endl;
    } else {
        std::cout << "No adjacent equal elements" << std::endl;
    }
    return 0;
}

