    Compare comp;
public:
    template<typename InputIt>
    SimpleMap(InputIt first, InputIt last, Compare c = Compare()) : comp(c) {
        while (first != last) {
            data.push_back(*first++);
        }
    }
    void print() const {
        for (const auto& k : data) std::cout << k << " ";
        std::cout << std::endl;
    }
};

