#include <iostream>
#include <mutex>
#include <thread>
#include <chrono>

int main() {
    std::timed_mutex mtx;

    std::thread t1([&mtx]() {
        mtx.lock();
        std::cout << "t1 acquired lock\n";
        std::this_thread::sleep_for(std::chrono::seconds(2));
        mtx.unlock();
        std::cout << "t1 released lock\n";
    });

    std::thread t2([&mtx]() {
        std::this_thread::sleep_for(std::chrono::seconds(1));
        if (mtx.try_lock_for(std::chrono::milliseconds(500))) {
            std::cout << "t2 acquired lock\n";
            mtx.unlock();
        } else {
            std::cout << "t2 failed to acquire lock (timeout)\n";
        }
    });

    t1.join();
    t2.join();
    return 0;
}

