#include <iostream>
#include <memory>

class Resource {
public:
    Resource() { std::cout << "Resource acquired\n"; }
    ~Resource() { std::cout << "Resource released\n"; }
};

int main() {
    // unique_ptr: exclusive ownership
    auto up = std::make_unique<Resource>();
    // Resource acquired

    // shared_ptr: shared ownership
    auto sp1 = std::make_shared<Resource>();
    // Resource acquired
    {
        auto sp2 = sp1;  // Shared reference
    }  // sp2 destroyed, but sp1 keeps it alive
    // Resource released (when sp1 goes out of scope)

    return 0;
    // All resources released
}

