#include <atomic>
#include <iostream>
#include <thread>

std::atomic<int> counter{0};

void incrementer() {
    int expected = 0;
    int desired = 1;
    while (!counter.compare_exchange_strong(expected, desired)) {
        expected = counter.load();  // Reload for retry
        desired = expected + 1;
    }
}

int main() {
    std::thread t1(incrementer);
    std::thread t2(incrementer);
    t1.join();
    t2.join();
    std::cout << "Final counter: " << counter.load() << std::endl;
    // Output may vary due to race, but demonstrates atomicity
    return 0;
}

