#include <vector>

// Predicate function: checks if two ints sum to more than 5
template<typename T>
bool sum_greater_than_five(T a, T b) {
    return a + b > 5;
}

// Function template with predicate parameter
template<typename Iter, typename Pred>
Iter adjacent_find(Iter begin, Iter end, Pred pred) {
    for (; begin != end - 1; ++begin) {
        if (pred(*begin, *(begin + 1))) {
            return begin;
        }
    }
    return end;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4};
    auto it = adjacent_find(vec.begin(), vec.end(), sum_greater_than_five);
    if (it != vec.end()) {
        std::cout << "Found adjacent pair at index " << (it - vec.begin()) << std::endl;
    } else {
        std::cout << "No adjacent pair found" << std::endl;
    }
    return 0;
}

