#include <iostream>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        sleep(2);
        std::cout << "Child process terminating." << std::endl;
        return 0;
    } else if (pid > 0) {
        // Parent process
        int status;
        std::cout << "Parent waiting for child..." << std::endl;
        wait(&status);
        std::cout << "Child has finished." << std::endl;
    } else {
        std::cerr << "Fork failed." << std::endl;
        return 1;
    }
    return 0;
}

