int main() {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        std::cout << "Child process exiting, creating zombie state.\n";
        exit(0);
    } else if (pid > 0) {
        // Parent process
        std::cout << "Parent sleeping; child is now a zombie.\n";
        sleep(3);  // Simulate delay, child remains zombie
        std::cout << "Parent calling wait to reap child.\n";
        wait(NULL);
        std::cout << "Zombie reaped, resources freed.\n";
    }
    return 0;
}

