#include <pthread.h>
#include <unistd.h>
#include <stdio.h>

void prepare() { printf("Prepare handler: before fork\n"); }
void parent() { printf("Parent handler: after fork in parent\n"); }
void child() { printf("Child handler: after fork in child\n"); }

int main() {
    pthread_atfork(prepare, parent, child);
    pid_t pid = fork();
