#include <setjmp.h>
#include <signal.h>
#include <stdio.h>

sigjmp_buf env;

int main() {
    sigset_t mask, oldmask, curmask;
    sigemptyset(&mask);
    sigaddset(&mask, SIGUSR1);
    sigprocmask(SIG_BLOCK, &mask, &oldmask);

    if (sigsetjmp(env, 1) == 0) {
        printf("At jump point: SIGUSR1 blocked\n");
        sigprocmask(SIG_UNBLOCK, &mask, NULL);
        printf("Unblocked SIGUSR1, now jumping\n");
        siglongjmp(env, 1);
    } else {
        printf("After siglongjmp: checking mask\n");
        sigprocmask(0, NULL, &curmask);
        if (sigismember(&curmask, SIGUSR1)) {
            printf("SIGUSR1 is blocked (restored)\n");
        } else {
            printf("SIGUSR1 is not blocked\n");
        }
        sigprocmask(SIG_SETMASK, &oldmask, NULL);
    }
    return 0;
}

