std::size_t my_find(const std::string& s, const std::string& substr, std::size_t pos = 0) {
    for (std::size_t i = pos; i + substr.size() <= s.size(); ++i) {
        bool match = true;
        for (std::size_t j = 0; j < substr.size(); ++j) {
            if (s[i + j] != substr[j]) {
                match = false;
                break;
            }
        }
        if (match) return i;
    }
    return std::string::npos;
}

int main() {
    std::string str = "hello world";
    std::size_t found = my_find(str, "world");
    std::cout << "Found at: " << found << std::endl;
    return 0;
}

