        std::cout << "Found: " << *it << std::endl;
    }

    // count
    std::cout << "Count of 2: " << s.count(2) << std::endl;

    // lower_bound and upper_bound
    auto lb = s.lower_bound(2);
    auto ub = s.upper_bound(2);
    std::cout << "Lower bound for 2: " << *lb << std::endl;
    std::cout << "Upper bound for 2: " << *ub << std::endl;

    // equal_range
    auto eq = s.equal_range(2);
    std::cout << "Equal range: from " << *eq.first << " to " << *eq.second << std::endl;

    return 0;
}

