class Resource {
private:
    int* ptr;
    size_t size;
public:
    Resource(size_t s) : size(s), ptr(new int[s]) {
        std::cout << "Constructor: allocated " << size << " ints\n";
    }
    Resource(Resource&& other) noexcept : ptr(other.ptr), size(other.size) {
        other.ptr = nullptr;
        other.size = 0;
        std::cout << "Move constructor: transferred resources\n";
    }
    ~Resource() {
        delete[] ptr;
        std::cout << "Destructor: freed resources\n";
    }
    size_t get_size() const { return size; }
};

int main() {
    Resource a(10);
    std::cout << "Original size: " << a.get_size() << "\n";
