template<typename Iter1, typename Iter2, typename OutputIter>
void my_merge(Iter1 first1, Iter1 last1, Iter2 first2, Iter2 last2, OutputIter dest) {
    while (first1 != last1 && first2 != last2) {
        if (*first2 < *first1) {
            *dest++ = *first2++;
        } else {
            *dest++ = *first1++;
        }
    }
    while (first1 != last1) *dest++ = *first1++;
    while (first2 != last2) *dest++ = *first2++;
}

