#include <iostream>

struct Node {
    int val;
    Node* left;
    Node* right;
    Node(int v) : val(v), left(nullptr), right(nullptr) {}
};

Node* insert(Node* root, int val) {
    if (!root) return new Node(val);
    if (val < root->val) root->left = insert(root->left, val);
    else if (val > root->val) root->right = insert(root->right, val);
    return root;
}

Node* lower_bound(Node* root, int key) {
    Node* curr = root;
    Node* res = nullptr;
    while (curr) {
        if (key <= curr->val) {
            res = curr;
            curr = curr->left;
        } else {
            curr = curr->right;
        }
    }
    return res;
}

int main() {
    Node* root = nullptr;
    root = insert(root, 10);
    root = insert(root, 5);
    root = insert(root, 15);
    root = insert(root, 7);
    Node* it = lower_bound(root, 6);
    std::cout << (it ? it->val : -1) << std::endl; // Outputs 7
    return 0;
}

