#include <iostream>
#include <vector>

class SimpleIterator {
private:
    int* current;
public:
    SimpleIterator(int* p) : current(p) {}
    int operator*() const { return *current; }
    SimpleIterator& operator++() { ++current; return *this; }
    bool operator!=(const SimpleIterator& other) const { return current != other.current; }
};

int main() {
    // Custom iterator for fixed array (no invalidation)
    int arr[] = {1, 2, 3};
    for (SimpleIterator it(arr), end(arr + 3); it != end; ++it) {
        std::cout << *it << " ";
    }
    std::cout << "\n";

    // STL vector: insertion invalidates iterators
    std::vector<int> v{1, 2, 3};
    auto it = v.begin() + 1;
    v.insert(it, 99);  // Invalidates 'it'
    // std::cout << *it;  // Undefined behavior!
    std::cout << "Vector after insert: ";
    for (int x : v) std::cout << x << " ";
    std::cout << std::endl;
    return 0;
}

