#include <iostream>

template<int N>
constexpr int factorial() {
    if constexpr (N <= 1) {
        return 1;
    } else {
        return N * factorial<N - 1>();
    }
}

template<bool UseFactorial>
constexpr int compute(int n) {
    if constexpr (UseFactorial) {
        return factorial<n>();
    } else {
        return n * 2;
    }
}

int main() {
    constexpr int f5 = compute<true>(5);  // 120 at compile time
    std::cout << f5 << std::endl;
    constexpr int d3 = compute<false>(3); // 6 at compile time
    std::cout << d3 << std::endl;
    return 0;
}

