// Runtime Polymorphism: Virtual functions
class Base {
public:
    virtual void func() { std::cout << "Base\n"; }
};
class Derived : public Base {
public:
    void func() override { std::cout << "Derived\n"; }
};

// Compile-time Polymorphism: Templates

template<typename T>
void templated_func(T val) {
    std::cout << "Template: " << val << "\n";
}

// Compile-time: Overloading
void overloaded_func(int x) { std::cout << "Int: " << x << "\n"; }
void overloaded_func(double x) { std::cout << "Double: " << x << "\n"; }

int main() {
    Base* b = new Derived();
    b->func();  // Runtime: Virtual call
    delete b;

    templated_func(42);  // Compile-time: Template
    overloaded_func(42); // Compile-time: Overload
    overloaded_func(3.14);
    return 0;
}

