#include <algorithm>
#include <iostream>
#include <vector>

template<typename ForwardIt1, typename ForwardIt2>
void my_swap_ranges(ForwardIt1 first1, ForwardIt1 last1, ForwardIt2 first2) {
    for (; first1 != last1; ++first1, ++first2) {
        std::swap(*first1, *first2);
    }
}

int main() {
    std::vector<int> a = {1, 2, 3};
    std::vector<int> b = {4, 5, 6};
    my_swap_ranges(a.begin(), a.end(), b.begin());
    for (int x : a) std::cout << x << ' ';
    std::cout << std::endl;
    for (int x : b) std::cout << x << ' ';
    std::cout << std::endl;
    return 0;
}

