#include <stdio.h>
#include <stdlib.h>

int main() {
    int *ptr = malloc(5 * sizeof(int));
    if (ptr == NULL) {
        fprintf(stderr, "Initial malloc failed\n");
        return 1;
    }

    // Unsafe: direct assignment loses original on failure
    // ptr = realloc(ptr, 10 * sizeof(int));

    // Safe: use temporary pointer
    int *temp = realloc(ptr, 10 * sizeof(int));
    if (temp == NULL) {
        fprintf(stderr, "realloc failed\n");
        free(ptr);
        return 1;
    }
    ptr = temp;

    // Now ptr points to resized block
    free(ptr);
    return 0;
}

#include <iostream>

int main() {
    // Misuse: Unsigned int in a subtracting loop leads to wrap-around bug
    unsigned int ui = 0;
    std::cout << "Misuse - ui - 1 = " << (ui - 1) << std::endl;  // Outputs large number (UINT_MAX)

    // Proper: Use signed int to avoid wrap-around
    int si = 0;
    std::cout << "Proper - si - 1 = " << (si - 1) << std::endl;  // Outputs -1

    // Proper: Unsigned for bit mask with explicit cast in mixed ops
    unsigned int mask = 0xFF;
    int value = -1;
    std::cout << "Proper mask op: " << ((int)(value & mask)) << std::endl;  // Cast to control promotion

    return 0;
}

