    for (i = 0; i < 50; i++) {
        small[i] = malloc(small_size);
        if (!small[i]) {
            printf("Failed small alloc at %d\n", i);
            return 1;
        }
    }

    // Free every other to fragment
    for (i = 0; i < 50; i += 2) {
        free(small[i]);
    }

    // Try large allocation (should fail due to fragmentation)
    void *large = malloc(small_size * 25);
    if (large) {
        printf("Large alloc succeeded (no fragmentation)\n");
        free(large);
    } else {
        printf("Large alloc failed (fragmentation)\n");
    }

    // Free remaining
    for (i = 1; i < 50; i += 2) {
        free(small[i]);
    }

    // Test limit: try huge allocation
    void *huge = malloc(1ULL << 30); // 1GB
    if (huge) {
        printf("Huge alloc succeeded\n");
        free(huge);
    } else {
        printf("Huge alloc failed (limit)\n");
    }

    return 0;
}

