#include <stdio.h>
#include <stdlib.h>

int main() {
    int capacity = 4;
    int size = 0;
    int *arr = malloc(capacity * sizeof(int));
    if (!arr) return 1;

    // Fill initial array
    for (int i = 0; i < capacity; i++) {
        arr[i] = i;
        size++;
    }

    // Grow array when full (double capacity)
    if (size >= capacity) {
        capacity *= 2;
        int *new_arr = realloc(arr, capacity * sizeof(int));
        if (!new_arr) {
            free(arr);
            return 1;
        }
        arr = new_arr;
        // Initialize new space
        for (int i = size; i < capacity; i++) {
            arr[i] = 0;
        }
        // Add one more element
        arr[size] = 4;
        size++;
    }

    // Print to verify
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    free(arr);
    return 0;
}

