int main() {
    const int N = 100;
    const size_t small = 1024;
    const size_t large = 40 * 1024; // 40KB
    void *blocks[N];

    // Allocate small blocks
    for(int i = 0; i < N; i++) {
        blocks[i] = malloc(small);
        if (blocks[i] == NULL) {
            printf("Failed to allocate small block %d\n", i);
            return 1;
        }
    }

    // Free every other block to create fragmentation
    for(int i = 0; i < N; i += 2) {
        free(blocks[i]);
    }

    // Try to allocate a large block (total free ~50KB, fragmented into 1KB pieces)
    void *big = malloc(large);
    if (big == NULL) {
        printf("Failed to allocate %zu bytes due to fragmentation\n", large);
    } else {
        printf("Allocated %zu bytes successfully\n", large);
        free(big);
    }

    // Clean up remaining blocks
    for(int i = 1; i < N; i += 2) {
        free(blocks[i]);
    }

    return 0;
}

