#include <iostream>

int main() {
    std::cout << "Operator Precedence and Short-Circuit Example:\n";

    // Short-circuit with logical &&: side effect avoided if left is false
    bool left = false;
    auto side = []() { std::cout << "Side effect called\n"; return true; };
    if (left && side()) {
        std::cout << "Logical &&: taken\n";
    } else {
        std::cout << "Logical &&: not taken (no side effect)\n";
    }

    // No short-circuit with bitwise &: side effect always called
    if (left & side()) {
        std::cout << "Bitwise &: taken\n";
    } else {
        std::cout << "Bitwise &: not taken (side effect happened)\n";
    }

    // Precedence: a || b && c parsed as a || (b && c)
    // If a is true, || short-circuits, skipping b && c
    auto a = [](){ std::cout << "a "; return true; };
    auto b = [](){ std::cout << "b "; return false; };
    auto c = [](){ std::cout << "c "; return true; };
    bool res = a() || b() && c();
    std::cout << "Result: " << res << " (only 'a' called due to short-circuit and precedence)\n";

    return 0;
}

