#include <semaphore.h>

int main() {
    sem_t sem;
    sem_init(&sem, 0, 0);

    std::thread t1([&sem]() {
        std::cout << "Thread 1: Waiting on semaphore...\n";
        sem_wait(&sem);
        std::cout << "Thread 1: Semaphore acquired!\n";
    });

    std::thread t2([&sem]() {
        std::this_thread::sleep_for(std::chrono::seconds(1));
        std::cout << "Thread 2: Posting to semaphore...\n";
        sem_post(&sem);
    });

    t1.join();
    t2.join();
    sem_destroy(&sem);
    return 0;
}

