#include <iostream>
#include <thread>
#include <semaphore>
#include <vector>
#include <chrono>

int main() {
    std::counting_semaphore<3> sem(3); // Allow up to 3 concurrent threads
    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back([&sem, i]() {
            sem.acquire();
            std::cout << "Thread " << i << " acquired semaphore\n";
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::cout << "Thread " << i << " released semaphore\n";
            sem.release();
        });
    }
    for (auto& t : threads) t.join();
    return 0;
}

