#include <setjmp.h>
#include <signal.h>
#include <stdio.h>

int main() {
    sigset_t mask, current;
    sigemptyset(&mask);
    sigaddset(&mask, SIGINT);
    sigprocmask(SIG_BLOCK, &mask, NULL);

    jmp_buf env;
    int val = sigsetjmp(env, 1);

    if (val == 0) {
        sigprocmask(SIG_UNBLOCK, &mask, NULL);
        printf("Signal mask changed (SIGINT unblocked)\n");
        siglongjmp(env, 1);
    } else {
        sigprocmask(0, NULL, &current);
        if (sigismember(&current, SIGINT)) {
            printf("Signal mask preserved (SIGINT blocked)\n");
        } else {
            printf("Signal mask not preserved\n");
        }
    }
    return 0;
}

